window.AUTH=window.AUTH||{};window.AUTH["24-354"]={"d":"24-354","id":"2024/24-354","n":"Federal Communications Commission v. Consumers’ Research","briefs":[{"k":"petitioner","label":"Brief of petitioners Federal Communications Commission, et al.","date":"2025-01-08","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/336896/20250108184903404_24-354ts_FCC.pdf","side":"pet","n":103},{"k":"petitioner","label":"Brief of petitioners SHLB Coalition, et al.","date":"2025-01-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/336927/20250109161556584_24-254%20SHLB%20et%20al.%20Opening%20Brief.pdf","side":"pet","n":113},{"k":"petitioner","label":"Brief of petitioners Competitive Carriers Association, et al.","date":"2025-01-09","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/336936/20250109184103303_250104a%20Pet%20Merits%20Brief%20for%20efiling.pdf","side":"pet","n":96},{"k":"respondent","label":"Brief of respondents Consumers' Research, et al.","date":"2025-02-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/342527/20250211165522207_24-354%20Brief%20for%20the%20Respondents.pdf","side":"res","n":140},{"k":"reply","label":"Reply of petitioners Competitive Carriers Association, et al.","date":"2025-03-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/352036/20250313124448746_2025-03-13%20Final%20CCA%20Reply.pdf","side":"pet","n":50},{"k":"reply","label":"Reply of petitioners SHLB Coalition, et al.","date":"2025-03-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-354/352091/20250313173609864_Reply%20Brief%20for%20SHLB%20et%20al.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us2r64_8nj9.pdf","tr":true,"items":[{"t":"case","label":"A.L.A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"op":10,"ar":4,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"0":"19, 20","2":"16, 24, 26","3":"3, 29, 47, 49, 50, 51, 57, 59, 60, 61, 74, 89","4":"8","5":"24"}},{"t":"case","label":"AT&T, Inc. v. FCC","cite":"886 F.3d 1236","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/886/1236/","by":{"0":"2","1":"3","2":"3","4":"5"}},{"t":"case","label":"Alenco Communications, Inc. v. FCC","cite":"201 F.3d 608","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/201/608/","op":1,"ar":2,"by":{"0":"29, 30","1":"24","3":"27, 50","5":"6"}},{"t":"case","label":"American Power & Light Co. v. SEC","cite":"329 U.S. 90","y":1946,"id":"scdb/1946-007","sc":1,"op":4,"sum":"that the orders were authorized by § 11 (b) (2) and that the section as so applied is constitutional. Pp. 96, 121.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 21, 24","2":"19, 24","3":"52, 65, 69","5":"13"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"591 U.S. 610","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"CFPB v. Community Financial Services Ass’n","cite":"601 U.S. 416","y":2024,"id":"2023/22-448","sc":1,"op":1,"sum":"Congress’ statutory authorization allowing the Consumer Financial Protection Bureau to draw money from the earnings of the Federal Reserve System to carry out the Bureau’s duties, 12 U. S. C. §§5497(a)(1), (2), satisfies the Appropriations Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 37","3":"37, 39","4":"3, 23","5":"16"}},{"t":"case","label":"Carter v. Carter Coal Co.","cite":"298 U.S. 238","y":1936,"id":"1900-1940/298us238","sc":1,"op":1,"sum":"In a 5 to 4 decision, the Court held that the 1935 Act overstepped the bounds of congressional power. The Court ruled that \"commerce\" is plainly distinct from \"production.\" Employing workers, setting wages and working hours, and mining coal were found to be part of the local process of production, separate from any trade of goods that could be regulated under the Commerce Clause.","sumSrc":"Oyez","by":{"0":"38, 39","1":"17","2":"35","3":"74, 76, 85, 86"}},{"t":"case","label":"Consumers’ Research v. FCC","cite":"67 F.4th 773","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/67/773/","by":{"0":"18, 29, 31, 38","1":"14","2":"9, 13, 20, 21, 35, 37, 42","3":"45, 83"}},{"t":"case","label":"Consumers’ Research v. FCC","cite":"88 F.4th 917","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/917/","by":{"0":"18, 38","1":"14","2":"9, 20, 35, 37","3":"3, 17, 25, 27, 30, 36, 45, 48, 49, 50, 53, 54, 56, 82, 87","4":"15, 16"}},{"t":"case","label":"Cospito v. Heckler","cite":"742 F.2d 2","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/742/2/","by":{"0":"39"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Currin v. Wallace","cite":"306 U.S. 1","y":1939,"id":"scdb/1938-107","sc":1,"sum":"(1) Such regulation, for the protection of sellers or purchasers, or both, is within the commerce power as respects the selling for transportation to other States or broad; and in view of the manner of the selling at the auctions, where all transactions are conducted indiscriminately and virtually at the same time, ConStatement of the Case. gress was authorized to apply its regulation to intrastate sales in order to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"17, 49","2":"15, 35","3":"86"}},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"op":11,"ar":3,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37, 46"}},{"t":"case","label":"Federal Energy Administration v. Algonquin SNG, Inc.","cite":"426 U.S. 548","y":1976,"id":"1975/75-382","sc":1,"sum":"Section 232 (b) authorizes the action taken by the President.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Federal Power Commission v. Hope Natural Gas Co.","cite":"320 U.S. 591","y":1944,"id":"1940-1955/320us591","sc":1,"op":3,"sum":"1. The validity of an order of the Federal Power Commission fixing rates under the Natural Gas Act is to be determined on judicial review by whether the impact or total effect of the order is just and reasonable rather than by the method of computing the rate base.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","2":"24","3":"71","5":"14"}},{"t":"case","label":"Field v. Clark","cite":"143 U.S. 649","y":1892,"id":"scdb/1891-139","sc":1,"op":1,"sum":"The signing by the Speaker of the House of Representatives and by the President of the Senate, in open session, of an enrolled bill, is an official attestation by the two Houses of such bill as one that has passed Congress; and when the bill thus attested receives the approval of the President, and is deposited in the Department of State according to law, its authentication as a bill that has passed Congress is …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"36","3":"40"}},{"t":"case","label":"Free Enterprise Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":4,"ar":2,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"49, 50","1":"16, 18, 51, 52, 53","2":"12, 45, 46, 47, 48","3":"89","4":"22, 23","5":"24"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Environmental Services (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Gibbons v. Ogden","cite":"9 Wheat. 1","y":1824,"url":"https://www.courtlistener.com/c/Wheat./9/1/","by":{"0":"35","5":"16"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"op":14,"ar":4,"sum":"Observing the traditional rule that Congress may make the effect of statutes conditional on facts found by the Executive.","sumSrc":"opinion","by":{"0":"20","1":"17, 26, 32, 35, 36","2":"16, 17, 19, 31, 32, 33, 34","3":"2, 19, 29, 30, 31, 33, 34, 40, 43, 46, 48, 58, 65, 66, 70, 71","4":"12, 13, 14","5":"12, 13, 14"}},{"t":"case","label":"Iowa Protection & Advocacy Services v. Tanager, Inc.","cite":"427 F.3d 541","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/427/541/","op":3,"by":{"0":"15, 16"}},{"t":"case","label":"J.W. Hampton, Jr., & Co. v. United States","cite":"276 U.S. 394","y":1928,"id":"1900-1940/276us394","sc":1,"op":20,"ar":4,"sum":"The Court held that Congress, within \"defined limits,\" could vest discretion in Executive officers to make public regulations and direct the details of statutory execution. The Court argued that the same principle that allowed Congress to fix rates in interstate commerce also enabled it to remit to a rate-making body under the control of the Executive branch.","sumSrc":"Oyez","by":{"0":"19, 36","1":"32, 51","2":"16, 19, 28","3":"46","4":"4, 8, 10","5":"12"}},{"t":"case","label":"Kingdomware Technologies, Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"op":2,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"0":"15","3":"91, 93, 94"}},{"t":"case","label":"Lebron v. National Railroad Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Lichter v. United States","cite":"334 U.S. 742","y":1948,"id":"scdb/1947-108","sc":1,"op":1,"sum":"1. The Renegotiation Act is constitutional on its face as authority for the recovery by the United States of \"excessive profits\" (less tax credits) realized by private parties in the circumstances of these cases on subcontracts for war goods in time of war with contractors who were also private parties--even in the absence of contractual provisions for the renegotiation of such profits and even as applied to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 33","3":"68, 69"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":4,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19","1":"26","2":"30","3":"61"}},{"t":"case","label":"MOAC Mall Holdings LLC v. Transform Holdco LLC","cite":"598 U.S. 288","y":2023,"id":"2022/21-1270","sc":1,"sum":"Section 363(m) of the Bankruptcy Code—which restricts the effects of certain successful appeals of judicially authorized sales or leases of bankruptcy-estate property—is not a jurisdictional provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"op":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":7,"ar":2,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"24","1":"32, 50, 51","2":"15, 19, 28, 29","3":"36, 66, 68","4":"7","5":"10"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"op":4,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"National Broadcasting Co. v. United States","cite":"319 U.S. 190","y":1943,"id":"scdb/1942-051","sc":1,"op":4,"sum":"1. The regulatory powers of the Federal Communications Commission are not limited to the engineering and technical aspects of radio communication.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 32","1":"32","2":"23","3":"68, 69","4":"4"}},{"t":"case","label":"Nebraska Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"sum":"The Court agreed with the trial judge that the murder case would generate \"intense and pervasive pretrial publicity.\" However, the unanimous court held that the practical problems associated with implementing a prior restraint on the press in this case would not have served the accused's rights.","sumSrc":"Oyez","by":{"0":"16","1":"18","3":"91, 92, 94"}},{"t":"case","label":"New York Central Securities Corp. v. United States","cite":"287 U.S. 12","y":1932,"id":"scdb/1932-039","sc":1,"op":1,"sum":"(.1) Under subdivision (2) the Commission may authorize a carrier that already controls others by stock ownership, to have control also by lease, for the purpose of securing greater economy and efficiency of operation. The disjunctive phrasing, \"either under a lease or by purchase of stock,\" does not mean that one method must be exclusive of the other. Pp. 22-23. (2) The extent of control allowable by the Commission …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","2":"24","3":"69","4":"4"}},{"t":"case","label":"New York City Employees’ Retirement System v. Dole Food Co.","cite":"969 F.2d 1430","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/969/1430/","by":{"0":"15"}},{"t":"case","label":"Newdow v. Roberts","cite":"603 F.3d 1002","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/603/1002/","op":1,"by":{"0":"15, 16"}},{"t":"case","label":"Oklahoma v. United States","cite":"62 F.4th 221","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/62/221/","op":1,"by":{"0":"39","3":"63"}},{"t":"case","label":"Opp Cotton Mills, Inc. v. Administrator","cite":"312 U.S. 126","y":1941,"id":"scdb/1940-093","sc":1,"op":1,"sum":"1. Wage and hours provisions of the Fair Labor Standards Act, as applied to manufacturers of textile goods for interstate commerce, held within the commerce power and consistent with the Fifth and Tenth Amendments. United States v. Darby, ante, p. 100.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","3":"71"}},{"t":"case","label":"Panama Refining Co. v. Ryan","cite":"293 U.S. 388","y":1935,"id":"1900-1940/293us388","sc":1,"op":5,"ar":3,"sum":"Writing for the 8-1 majority, Chief Justice Charles E. Hughes concluded the order was not constitutional. Supreme Court held that in enacting the order, the President subsumed legislative powers that Congress does not have the power to delegate. Congress cannot delegate legislative powers to other branches of government in order to sustain the democratic system of government.","sumSrc":"Oyez","by":{"0":"19, 20, 24","2":"24, 26, 29","3":"3, 40, 52, 59, 60, 68","4":"8"}},{"t":"case","label":"Pensacola Telegraph, Co. v. Western Union Telegraph Co.","cite":"96 U.S 1","y":1878,"url":"https://www.courtlistener.com/c/U.S/96/1/","by":{"0":"35"}},{"t":"case","label":"Pierce County v. Guillen","cite":"537 U.S. 129","y":2003,"id":"2002/01-1229","sc":1,"sum":"The Court held that both the original program and its subsequent amendments fall within Congress's Commerce Clause power to \"'regulate the use of the channels of interstate commerce'\" and \"'to regulate and protect the instrumentalities of interstate commerce.'\" The Court concluded that, because Congress could reasonably believe that adopting a measure eliminating an unforeseen side effect of the Program's information-gathering requirement would result in greater safety on the nation's roads, the legislation was aimed at improving safety in the channels of commerce and increasing protections for the instrumentalities of interstate commerce.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Qwest Corp. v. FCC","cite":"258 F.3d 1191","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/258/1191/","op":2,"by":{"0":"31, 34","1":"26, 29","2":"5, 21, 22, 26","3":"53","5":"8, 12"}},{"t":"case","label":"R.H. Johnson & Co. v. SEC","cite":"198 F.2d 690","y":1952,"url":"https://www.courtlistener.com/c/F.2d/198/690/","by":{"0":"39"}},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"sum":"A case in which the Court struck down several Texas laws that criminalized abortion, holding that laws that impose an undue burden on a woman’s right to seek an abortion violate her fundamental right to privacy under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"15","3":"94"}},{"t":"case","label":"SEC v. Sloan","cite":"436 U.S. 103","y":1978,"id":"1977/76-1607","sc":1,"op":1,"sum":"The Court held that the Securities and Exchange Commission lacks authority under § 12(k) of the Securities Exchange Act of 1934 to issue multiple consecutive 10-day orders for the suspension of trading of a company's stock.","sumSrc":"Oyez","by":{"0":"15","3":"93"}},{"t":"case","label":"Skinner v. Mid-America Pipeline Co.","cite":"490 U.S. 212","y":1989,"id":"1988/87-2098","sc":1,"op":15,"ar":12,"sum":"Section 7005 of COBRA is not an unconstitutional delegation of the taxing power by Congress to the Executive Branch.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36","1":"35","3":"26, 46, 65, 66, 67, 72","4":"7, 10","5":"13"}},{"t":"case","label":"Sorrell v. SEC","cite":"679 F.2d 1323","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/679/1323/","by":{"0":"40"}},{"t":"case","label":"Southern Pacific Terminal Co. v. ICC","cite":"219 U.S. 498","y":1911,"id":"scdb/1910-080","sc":1,"sum":"The case is not moot where interests <jf a public character are asserted by the Government under conditions that may be immediately repeated, merely because the particular order involved has expired. United States v. Trans-Missouri Freight Assn., 166 U. S. 290, 308.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15","2":"53-54","3":"94, 96"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Sunshine Anthracite Coal Co. v. Adkins","cite":"310 U.S. 381","y":1940,"id":"scdb/1939-119","sc":1,"op":5,"ar":1,"sum":"1. The 192% tax imposed by § 3 (b) of the Bituminous Coal Conservation Act (1937) on sales of such coal by producers, \"which would be subject to the application of the conditions and provisions' of the code provided for in § 4, or of the provisions of § 4A,\" applies to producers who. are not members of the code, although under § 4 the provisions of the code are for code members only. P. 391. A contrary construction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 45, 49","1":"17, 33, 40, 45, 49","2":"14, 35, 44","3":"46, 79, 85, 88","4":"4, 16, 22","5":"22"}},{"t":"case","label":"Texas Office of Public Utility Counsel v. FCC","cite":"183 F.3d 393","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/183/393/","by":{"0":"34","1":"22, 26, 28, 29","2":"5, 26","3":"6, 47, 49, 53, 55, 56","5":"7, 12, 17"}},{"t":"case","label":"The Pittston Co. v. United States","cite":"368 F.3d 385","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/385/","by":{"0":"39"}},{"t":"case","label":"Todd & Co. v. SEC","cite":"557 F.2d 1008","y":1977,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/557/1008/","by":{"0":"39"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"594 U.S. 413","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"Union Bridge Co. v. United States","cite":"204 U.S. 364","y":1907,"id":"scdb/1906-156","sc":1,"sum":"Commerce comprehends navigation; and to-freé navigation from unreasonable obstructions by compelling the removal of bridges which are such obstructions is alegitimate’ exercise by Congress o'f its power to regulate commerce. \"","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20","3":"70, 71"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"op":1,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"United States v. Frame","cite":"885 F.2d 1119","y":1989,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/885/1119/","by":{"0":"39"}},{"t":"case","label":"United States v. Grimaud","cite":"220 U.S. 506","y":1911,"id":"scdb/1910-122","sc":1,"sum":"Under the acts establishing forest reservations, their use for grazing or other lawful purposes is subject to rules and regulations established by the Secretary of Agriculture, and it being impracticable for Congress to provide general regulations, that body acted within its constitutional power in conferring power on the Secretary to establish such rules; the power so conferred being administrative and not …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21","3":"69"}},{"t":"case","label":"United States v. Raddatz","cite":"447 U.S. 667","y":1980,"id":"1979/79-8","sc":1,"sum":"The Supreme Court held that the FMA did not did not require the district court to independently review disputed testimony. Also, the FMA did not violate the Constitution. Justice Harry A. Blackmun concurred, writing that the statute in question does not threaten judicial power or independence in judicial decision making.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Rock Royal Co-operative, Inc.","cite":"307 U.S. 533","y":1939,"id":"scdb/1938-046","sc":1,"op":1,"sum":"Under the Agricultural Marketing Agreement Act of 1937, the Secretary of Agriculture, after notice and hearings, made an order for fixing and equalizing minimum prices to be paid producers for milk sold to dealers (\"handlers\") and disposed of by the latter either in liquid form or as milk products within a \"marketing area\" comprising the City of New York and adjacent counties. Efforts to secure the consent of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 41","3":"47, 48, 53, 54, 66, 85","5":"7"}},{"t":"case","label":"United States v. Sanchez-Gomez","cite":"584 U.S. 381","y":2018,"id":"2017/17-312","sc":1,"sum":"The Court held that challenges to the federal district-wide policy of using of pretrial physical restraints are moot.","sumSrc":"Oyez","by":{"0":"14, 15"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"590 U.S. 371","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"0":"47","4":"21"}},{"t":"case","label":"University of Texas v. Camenisch","cite":"451 U.S. 390","y":1981,"id":"1980/80-317","sc":1,"sum":"The question whether a preliminary injunction should have been issued is moot because the terms of the injunction have been fully and irrevocably carried out, but, as the Court of Appeals correctly noted, the question whether the University must pay for the interpreter remains for trial on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Vermont Agency of Natural Resources v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":2,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Walmsley v. FTC","cite":"117 F.4th 1032","y":2024,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/117/1032/","by":{"0":"40"}},{"t":"case","label":"Wayman v. Southard","cite":"10 Wheat. 1","y":1825,"url":"https://www.courtlistener.com/c/Wheat./10/1/","op":3,"by":{"0":"19, 24"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":13,"ar":3,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"20, 21, 24, 29, 30, 33","1":"33","2":"23, 24, 25","3":"19, 31, 45, 48, 50, 66, 70, 72, 83","4":"9, 15","5":"6, 10"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"ar":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"21, 38","1":"33, 36, 51","2":"15, 28, 32","3":"68, 71","4":"12","5":"9, 13"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"40, 45"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"12, 17, 30"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","stext":{"head":"§151. Purposes of chapter; Federal Communications Commission created","paras":[[0,"For the purpose of regulating interstate and foreign commerce in communication by wire and radio so as to make available, so far as possible, to all the people of the United States, without discrimination on the basis of race, color, religion, national origin, or sex, a rapid, efficient, Nation-wide, and world-wide wire and radio communication service with adequate facilities at reasonable charges, for the purpose of the national defense, for the purpose of promoting safety of life and property through the use of wire and radio communications, and for the purpose of securing a more effective execution of this policy by centralizing authority heretofore granted by law to several agencies and by granting additional authority with respect to interstate and foreign commerce in wire and radio communication, there is created a commission to be known as the \"Federal Communications Commission\", which shall be constituted as hereinafter provided, and which shall execute and enforce the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/151?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§151. Purposes of chapter; Federal Communications Commission created","tname":"Telecommunications","by":{"0":"2, 2","1":"2, 20","2":"3","4":"5"}},{"t":"usc","label":"47 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/47/154","subs":["(i)"],"stext":{"head":"§154. Federal Communications Commission","paras":[[0,"(a) Number of commissioners; appointment"],[0,"The Federal Communications Commission (in this chapter referred to as the \"Commission\") shall be composed of five commissioners appointed by the President, by and with the advice and consent of the Senate, one of whom the President shall designate as chairman."],[0,"(b) Qualifications"],[0,"(1) Each member of the Commission shall be a citizen of the United States."],[0,"(2)(A) No member of the Commission or person employed by the Commission shall—"],[1,"(i) be financially interested in any company or other entity engaged in the manufacture or sale of telecommunications equipment which is subject to regulation by the Commission;"],[1,"(ii) be financially interested in any company or other entity engaged in the business of communication by wire or radio or in the use of the electromagnetic spectrum;"],[1,"(iii) be financially interested in any company or other entity which controls any company or other entity specified in clause (i) or clause (ii), or which derives a significant portion of its total income from ownership of stocks, bonds, or other securities of any such company or other entity; or"],[1,"(iv) be employed by, hold any official relation to, or own any stocks, bonds, or other securities of, any person significantly regulated by the Commission under this chapter;"],[0,"except that the prohibitions established in this subparagraph shall apply only to financial interests in any company or other entity which has a significant interest in communications, manufacturing, or sales activities which are subject to regulation by the Commission."],[0,"(B)(i) The Commission shall have authority to waive, from time to time, the application of the prohibitions established in subparagraph (A) to persons employed by the Commission if the Commission determines that the financial interests of a person which are involved in a particular case are minimal, except that such waiver authority shall be subject to the provisions of section 208 of title 18. The waiver authority established in this subparagraph shall not apply with respect to members of the Commission."],[0,"(ii) In any case in which the Commission exercises the waiver authority established in this subparagraph, the Commission shall publish notice of such action in the Federal Register."],[0,"(3) The Commission, in determining whether a company or other entity has a significant interest in communications, manufacturing, or sales activities which are subject to regulation by the Commission, shall consider (without excluding other relevant factors)—"],[1,"(A) the revenues, investments, profits, and managerial efforts directed to the related communications, manufacturing, or sales activities of the company or other entity involved, as compared to the other aspects of the business of such company or other entity;"],[1,"(B) the extent to which the Commission regulates and oversees the activities of such company or other entity;"],[1,"(C) the degree to which the economic interests of such company or other entity may be affected by any action of the Commission; and"],[1,"(D) the perceptions held by the public regarding the business activities of such company or other entity."],[0,"(4) Members of the Commission shall not engage in any other business, vocation, profession, or employment while serving as such members."],[0,"(5) The maximum number of commissioners who may be members of the same political party shall be a number equal to the least number of commissioners which constitutes a majority of the full membership of the Commission."],[0,"(c) Terms of office; vacancies"],[0,"(1) A commissioner—"],[1,"(A) shall be appointed for a term of 5 years;"],[1,"(B) except as provided in subparagraph (C), may continue to serve after the expiration of the fixed term of office of the commissioner until a successor is appointed and has been confirmed and taken the oath of office; and"],[1,"(C) may not continue to serve after the expiration of the session of Congress that begins after the expiration of the fixed term of office of the commissioner."],[0,"(2) Any person chosen to fill a vacancy in the Commission—"],[1,"(A) shall be appointed for the unexpired term of the commissioner that the person succeeds;"],[1,"(B) except as provided in subparagraph (C), may continue to serve after the expiration of the fixed term of office of the commissioner that the person succeeds until a successor is appointed and has been confirmed and taken the oath of office; and"],[1,"(C) may not continue to serve after the expiration of the session of Congress that begins after the expiration of the fixed term of office of the commissioner that the person succeeds."],[0,"(3) No vacancy in the Commission shall impair the right of the remaining commissioners to exercise all the powers of the Commission."],[0,"(d) Compensation of Commission members"],[0,"Each Commissioner shall receive an annual salary at the annual rate payable from time to time for level IV of the Executive Schedule, payable in monthly installments. The Chairman of the Commission, during the period of his service as Chairman, shall receive an annual salary at the annual rate payable from time to time for level III of the Executive Schedule."],[0,"(e) Principal office; special sessions"],[0,"The principal office of the Commission shall be in the District of Columbia, where its general sessions shall be held; but whenever the convenience of the public or of the parties may be promoted or delay or expense prevented thereby, the Commission may hold special sessions in any part of the United States."],[0,"(f) Employees and assistants; compensation of members of Field Engineering and Monitoring Bureau; use of amateur volunteers for certain purposes; commercial radio operator examinations"],[0,"(1) The Commission shall have authority, subject to the provisions of the civil-service laws and chapter 51 and subchapter III of chapter 53 of title 5, to appoint such officers, engineers, accountants, attorneys, inspectors, examiners, and other employees as are necessary in the exercise of its functions."],[0,"(2) Without regard to the civil-service laws, but subject to chapter 51 and subchapter III of chapter 53 of title 5, each commissioner may appoint three professional assistants and a secretary, each of whom shall perform such duties as such commissioner shall direct. In addition, the chairman of the Commission may appoint, without regard to the civil-service laws, but subject to chapter 51 and subchapter III of chapter 53 of title 5, and administrative assistant who shall perform such duties as the chairman shall direct."],[0,"(3) The Commission shall fix a reasonable rate of extra compensation for overtime services of engineers in charge and radio engineers of the Field Engineering and Monitoring Bureau of the Federal Communications Commission, who may be required to remain on duty between the hours of 5 o'clock postmeridian and 8 o'clock antemeridian or on Sundays or holidays to perform services in connection with the inspection of ship radio equipment and apparatus for the purposes of part II of subchapter III of this chapter or the Great Lakes Agreement, on the basis of one-half day's additional pay for each two hours or fraction thereof of at least one hour that the overtime extends beyond 5 o'clock postmeridian (but not to exceed two and one-half days' pay for the full period from 5 o'clock postmeridian to 8 o'clock antemeridian) and two additional days' pay for Sunday or holiday duty. The said extra compensation for overtime services shall be paid by the master, owner, or agent of such vessel to the local United States collector of customs or his representative, who shall deposit such collection into the Treasury of the United States to an appropriately designated receipt account: Provided, That the amounts of such collections received by the said collector of customs or his representatives shall be covered into the Treasury as miscellaneous receipts; and the payments of such extra compensation to the several employees entitled thereto shall be made from the annual appropriations for salaries and expenses of the Commission: Provided further, That to the extent that the annual appropriations which are authorized to be made from the general fund of the Treasury are insufficient, there are authorized to be appropriated from the general fund of the Treasury such additional amounts as may be necessary to the extent that the amounts of such receipts are in excess of the amounts appropriated: Provided further, That such extra compensation shall be paid if such field employees have been ordered to report for duty and have so reported whether the actual inspection of the radio equipment or apparatus takes place or not: And provided further, That in those ports where customary working hours are other than those hereinabove mentioned, the engineers in charge are vested with authority to regulate the hours of such employees so as to agree with prevailing working hours in said ports where inspections are to be made, but nothing contained in this proviso shall be construed in any manner to alter the length of a working day for the engineers in charge and radio engineers or the overtime pay herein fixed: and Provided further, That, in the alternative, an entity designated by the Commission may make the inspections referred to in this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/154?type=usc&year=mostrecent&link-type=html"},"head":"§154. Federal Communications Commission","tname":"Telecommunications","by":{"0":"48","1":"20, 47"}},{"t":"usc","label":"47 U.S.C. § 214","url":"https://www.law.cornell.edu/uscode/text/47/214","subs":["(e)","(e)(1)","(e)(5)","(e)(2)"],"stext":{"head":"§214. Extension of lines or discontinuance of service; certificate of public convenience and necessity","paras":[[0,"(a) Exceptions; temporary or emergency service or discontinuance of service; changes in plant, operation or equipment"],[0,"No carrier shall undertake the construction of a new line or of an extension of any line, or shall acquire or operate any line, or extension thereof, or shall engage in transmission over or by means of such additional or extended line, unless and until there shall first have been obtained from the Commission a certificate that the present or future public convenience and necessity require or will require the construction, or operation, or construction and operation, of such additional or extended line: Provided, That no such certificate shall be required under this section for the construction, acquisition, or operation of (1) a line within a single State unless such line constitutes part of an interstate line, (2) local, branch, or terminal lines not exceeding ten miles in length, or (3) any line acquired under section 221 of this title: Provided further, That the Commission may, upon appropriate request being made, authorize temporary or emergency service, or the supplementing of existing facilities, without regard to the provisions of this section. No carrier shall discontinue, reduce, or impair service to a community, or part of a community, unless and until there shall first have been obtained from the Commission a certificate that neither the present nor future public convenience and necessity will be adversely affected thereby; except that the Commission may, upon appropriate request being made, authorize temporary or emergency discontinuance, reduction, or impairment of service, or partial discontinuance, reduction, or impairment of service, without regard to the provisions of this section. As used in this section the term \"line\" means any channel of communication established by the use of appropriate equipment, other than a channel of communication established by the interconnection of two or more existing channels: Provided, however, That nothing in this section shall be construed to require a certificate or other authorization from the Commission for any installation, replacement, or other changes in plant, operation, or equipment, other than new construction, which will not impair the adequacy or quality of service provided."],[0,"(b) Notification of Secretary of Defense, Secretary of State, and State Governor"],[0,"Upon receipt of an application for any such certificate, the Commission shall cause notice thereof to be given to, and shall cause a copy of such application to be filed with, the Secretary of Defense, the Secretary of State (with respect to such applications involving service to foreign points), and the Governor of each State in which such line is proposed to be constructed, extended, acquired, or operated, or in which such discontinuance, reduction, or impairment of service is proposed, with the right to those notified to be heard; and the Commission may require such published notice as it shall determine."],[0,"(c) Approval or disapproval; injunction"],[0,"The Commission shall have power to issue such certificate as applied for, or to refuse to issue it, or to issue it for a portion or portions of a line, or extension thereof, or discontinuance, reduction, or impairment of service, described in the application, or for the partial exercise only of such right or privilege, and may attach to the issuance of the certificate such terms and conditions as in its judgment the public convenience and necessity may require. After issuance of such certificate, and not before, the carrier may, without securing approval other than such certificate, comply with the terms and conditions contained in or attached to the issuance of such certificate and proceed with the construction, extension, acquisition, operation, or discontinuance, reduction, or impairment of service covered thereby. Any construction, extension, acquisition, operation, discontinuance, reduction, or impairment of service contrary to the provisions of this section may be enjoined by any court of competent jurisdiction at the suit of the United States, the Commission, the State commission, any State affected, or any party in interest."],[0,"(d) Order of Commission; hearing; penalty"],[0,"The Commission may, after full opportunity for hearing, in a proceeding upon complaint or upon its own initiative without complaint, authorize or require by order any carrier, party to such proceeding, to provide itself with adequate facilities for the expeditious and efficient performance of its service as a common carrier and to extend its line or to establish a public office; but no such authorization or order shall be made unless the Commission finds, as to such provision of facilities, as to such establishment of public offices, or as to such extension, that it is reasonably required in the interest of public convenience and necessity, or as to such extension or facilities that the expense involved therein will not impair the ability of the carrier to perform its duty to the public. Any carrier which refuses or neglects to comply with any order of the Commission made in pursuance of this subsection shall forfeit to the United States $1,200 for each day during which such refusal or neglect continues."],[0,"(e) Provision of universal service"],[0,"(1) Eligible telecommunications carriers"],[1,"A common carrier designated as an eligible telecommunications carrier under paragraph (2), (3), or (6) shall be eligible to receive universal service support in accordance with section 254 of this title and shall, throughout the service area for which the designation is received—"],[2,"(A) offer the services that are supported by Federal universal service support mechanisms under section 254(c) of this title, either using its own facilities or a combination of its own facilities and resale of another carrier's services (including the services offered by another eligible telecommunications carrier); and"],[2,"(B) advertise the availability of such services and the charges therefor using media of general distribution."],[0,"(2) Designation of eligible telecommunications carriers"],[1,"A State commission shall upon its own motion or upon request designate a common carrier that meets the requirements of paragraph (1) as an eligible telecommunications carrier for a service area designated by the State commission. Upon request and consistent with the public interest, convenience, and necessity, the State commission may, in the case of an area served by a rural telephone company, and shall, in the case of all other areas, designate more than one common carrier as an eligible telecommunications carrier for a service area designated by the State commission, so long as each additional requesting carrier meets the requirements of paragraph (1). Before designating an additional eligible telecommunications carrier for an area served by a rural telephone company, the State commission shall find that the designation is in the public interest."],[0,"(3) Designation of eligible telecommunications carriers for unserved areas"],[1,"If no common carrier will provide the services that are supported by Federal universal service support mechanisms under section 254(c) of this title to an unserved community or any portion thereof that requests such service, the Commission, with respect to interstate services or an area served by a common carrier to which paragraph (6) applies, or a State commission, with respect to intrastate services, shall determine which common carrier or carriers are best able to provide such service to the requesting unserved community or portion thereof and shall order such carrier or carriers to provide such service for that unserved community or portion thereof. Any carrier or carriers ordered to provide such service under this paragraph shall meet the requirements of paragraph (1) and shall be designated as an eligible telecommunications carrier for that community or portion thereof."],[0,"(4) Relinquishment of universal service"],[1,"A State commission (or the Commission in the case of a common carrier designated under paragraph (6)) shall permit an eligible telecommunications carrier to relinquish its designation as such a carrier in any area served by more than one eligible telecommunications carrier. An eligible telecommunications carrier that seeks to relinquish its eligible telecommunications carrier designation for an area served by more than one eligible telecommunications carrier shall give advance notice to the State commission (or the Commission in the case of a common carrier designated under paragraph (6)) of such relinquishment. Prior to permitting a telecommunications carrier designated as an eligible telecommunications carrier to cease providing universal service in an area served by more than one eligible telecommunications carrier, the State commission (or the Commission in the case of a common carrier designated under paragraph (6)) shall require the remaining eligible telecommunications carrier or carriers to ensure that all customers served by the relinquishing carrier will continue to be served, and shall require sufficient notice to permit the purchase or construction of adequate facilities by any remaining eligible telecommunications carrier. The State commission (or the Commission in the case of a common carrier designated under paragraph (6)) shall establish a time, not to exceed one year after the State commission (or the Commission in the case of a common carrier designated under paragraph (6)) approves such relinquishment under this paragraph, within which such purchase or construction shall be completed."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/214?type=usc&year=mostrecent&link-type=html"},"head":"§214. Extension of lines or discontinuance of service; certificate of public convenience and necessity","tname":"Telecommunications","by":{"0":"27, 27, 27","1":"22, 36","2":"20"}},{"t":"usc","label":"47 U.S.C. § 254","url":"https://www.law.cornell.edu/uscode/text/47/254","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(3)","(b)(4)","(b)(5)","(b)(6)","(b)(7)","(c)","(c)(1)","(d)","(e)","(h)","(h)(1)","(h)(1)(A)","(h)(1)(B)","(c)(1)(A)","(c)(1)(B)","(c)(1)(C)","(c)(1)(D)","(c)(3)","(h)(2)(A)","(h)(4)","(h)(7)(A)","(i)"],"stext":{"head":"§254. Universal service","paras":[[0,"(a) Procedures to review universal service requirements"],[0,"(1) Federal-State Joint Board on universal service"],[1,"Within one month after February 8, 1996, the Commission shall institute and refer to a Federal-State Joint Board under section 410(c) of this title a proceeding to recommend changes to any of its regulations in order to implement sections 214(e) of this title and this section, including the definition of the services that are supported by Federal universal service support mechanisms and a specific timetable for completion of such recommendations. In addition to the members of the Joint Board required under section 410(c) of this title, one member of such Joint Board shall be a State-appointed utility consumer advocate nominated by a national organization of State utility consumer advocates. The Joint Board shall, after notice and opportunity for public comment, make its recommendations to the Commission 9 months after February 8, 1996."],[0,"(2) Commission action"],[1,"The Commission shall initiate a single proceeding to implement the recommendations from the Joint Board required by paragraph (1) and shall complete such proceeding within 15 months after February 8, 1996. The rules established by such proceeding shall include a definition of the services that are supported by Federal universal service support mechanisms and a specific timetable for implementation. Thereafter, the Commission shall complete any proceeding to implement subsequent recommendations from any Joint Board on universal service within one year after receiving such recommendations."],[0,"(b) Universal service principles"],[0,"The Joint Board and the Commission shall base policies for the preservation and advancement of universal service on the following principles:"],[0,"(1) Quality and rates"],[1,"Quality services should be available at just, reasonable, and affordable rates."],[0,"(2) Access to advanced services"],[1,"Access to advanced telecommunications and information services should be provided in all regions of the Nation."],[0,"(3) Access in rural and high cost areas"],[1,"Consumers in all regions of the Nation, including low-income consumers and those in rural, insular, and high cost areas, should have access to telecommunications and information services, including interexchange services and advanced telecommunications and information services, that are reasonably comparable to those services provided in urban areas and that are available at rates that are reasonably comparable to rates charged for similar services in urban areas."],[0,"(4) Equitable and nondiscriminatory contributions"],[1,"All providers of telecommunications services should make an equitable and nondiscriminatory contribution to the preservation and advancement of universal service."],[0,"(5) Specific and predictable support mechanisms"],[1,"There should be specific, predictable and sufficient Federal and State mechanisms to preserve and advance universal service."],[0,"(6) Access to advanced telecommunications services for schools, health care, and libraries"],[1,"Elementary and secondary schools and classrooms, health care providers, and libraries should have access to advanced telecommunications services as described in subsection (h)."],[0,"(7) Additional principles"],[1,"Such other principles as the Joint Board and the Commission determine are necessary and appropriate for the protection of the public interest, convenience, and necessity and are consistent with this chapter."],[0,"(c) Definition"],[0,"(1) In general"],[1,"Universal service is an evolving level of telecommunications services that the Commission shall establish periodically under this section, taking into account advances in telecommunications and information technologies and services. The Joint Board in recommending, and the Commission in establishing, the definition of the services that are supported by Federal universal service support mechanisms shall consider the extent to which such telecommunications services—"],[2,"(A) are essential to education, public health, or public safety;"],[2,"(B) have, through the operation of market choices by customers, been subscribed to by a substantial majority of residential customers;"],[2,"(C) are being deployed in public telecommunications networks by telecommunications carriers; and"],[2,"(D) are consistent with the public interest, convenience, and necessity."],[0,"(2) Alterations and modifications"],[1,"The Joint Board may, from time to time, recommend to the Commission modifications in the definition of the services that are supported by Federal universal service support mechanisms."],[0,"(3) Special services"],[1,"In addition to the services included in the definition of universal service under paragraph (1), the Commission may designate additional services for such support mechanisms for schools, libraries, and health care providers for the purposes of subsection (h)."],[0,"(d) Telecommunications carrier contribution"],[0,"Every telecommunications carrier that provides interstate telecommunications services shall contribute, on an equitable and nondiscriminatory basis, to the specific, predictable, and sufficient mechanisms established by the Commission to preserve and advance universal service. The Commission may exempt a carrier or class of carriers from this requirement if the carrier's telecommunications activities are limited to such an extent that the level of such carrier's contribution to the preservation and advancement of universal service would be de minimis. Any other provider of interstate telecommunications may be required to contribute to the preservation and advancement of universal service if the public interest so requires."],[0,"(e) Universal service support"],[0,"After the date on which Commission regulations implementing this section take effect, only an eligible telecommunications carrier designated under section 214(e) of this title shall be eligible to receive specific Federal universal service support. A carrier that receives such support shall use that support only for the provision, maintenance, and upgrading of facilities and services for which the support is intended. Any such support should be explicit and sufficient to achieve the purposes of this section."],[0,"(f) State authority"],[0,"A State may adopt regulations not inconsistent with the Commission's rules to preserve and advance universal service. Every telecommunications carrier that provides intrastate telecommunications services shall contribute, on an equitable and nondiscriminatory basis, in a manner determined by the State to the preservation and advancement of universal service in that State. A State may adopt regulations to provide for additional definitions and standards to preserve and advance universal service within that State only to the extent that such regulations adopt additional specific, predictable, and sufficient mechanisms to support such definitions or standards that do not rely on or burden Federal universal service support mechanisms."],[0,"(g) Interexchange and interstate services"],[0,"Within 6 months after February 8, 1996, the Commission shall adopt rules to require that the rates charged by providers of interexchange telecommunications services to subscribers in rural and high cost areas shall be no higher than the rates charged by each such provider to its subscribers in urban areas. Such rules shall also require that a provider of interstate interexchange telecommunications services shall provide such services to its subscribers in each State at rates no higher than the rates charged to its subscribers in any other State."],[0,"(h) Telecommunications services for certain providers"],[0,"(1) In general"],[0,"(A) Health care providers for rural areas"],[2,"A telecommunications carrier shall, upon receiving a bona fide request, provide telecommunications services which are necessary for the provision of health care services in a State, including instruction relating to such services, to any public or nonprofit health care provider that serves persons who reside in rural areas in that State at rates that are reasonably comparable to rates charged for similar services in urban areas in that State. A telecommunications carrier providing service under this paragraph shall be entitled to have an amount equal to the difference, if any, between the rates for services provided to health care providers for rural areas in a State and the rates for similar services provided to other customers in comparable rural areas in that State treated as a service obligation as a part of its obligation to participate in the mechanisms to preserve and advance universal service."],[0,"(B) Educational providers and libraries"],[2,"All telecommunications carriers serving a geographic area shall, upon a bona fide request for any of its services that are within the definition of universal service under subsection (c)(3), provide such services to elementary schools, secondary schools, and libraries for educational purposes at rates less than the amounts charged for similar services to other parties. The discount shall be an amount that the Commission, with respect to interstate services, and the States, with respect to intrastate services, determine is appropriate and necessary to ensure affordable access to and use of such services by such entities. A telecommunications carrier providing service under this paragraph shall—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/254?type=usc&year=mostrecent&link-type=html"},"op":47,"ar":5,"head":"§254. Universal service","tname":"Telecommunications","by":{"0":"32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32, 32","1":"i, 4, 29, 33, 5, 36, 5, 36, 5, 8, 24, 36, 37, 5, 36, 5, 9, 23, 36, 6, 36, 6, 29, i, 30, 35, 4, 22, 33, 36, 4, 28, 4, 27, 37, 4, 27, 37, 4, 22, i, 6, 9, 10, 21, 23, 33, 36, 6, 8, 9, 20, 22, 27, 30, 33, 36, i, 33, 6, 9, 23, 24, 37, 6, 9, 23, 24, 30, 37, 24, 25, 30, 30, 23","2":"4, 33, 4, 21, 26, 20, 35, 21, 23, 35, 4, 4, 6, 20, 33, 35, 21, 35, 5","3":"6, 10, 18, 26, 29, 44, 45, 46, 49, 54, 55, 57, 59, 60, 64, 65, 70, 72, 7, 26, 47, 49, 50, 51, 53, 56, 59, 8, 26, 54, 55, 8, 26, 56, 57, 59, 59, 59","4":"6, 6, 12, 13, 6, 12, 13, 6, 12, 13, 6, 12, 13","5":"8, 9, 5, 9, 6, 10, 3, 6, 2, 6, 7, 15, 2, 6"}},{"t":"usc","label":"47 U.S.C. § 608","url":"https://www.law.cornell.edu/uscode/text/47/608","by":{"0":"32"}},{"t":"law","label":"Pub. L. No. 104-104","url":"https://www.govinfo.gov/link/plaw/104/public/104","by":{"0":"3","3":"6","4":"5"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(c)"],"by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 2073","url":"https://www.law.cornell.edu/uscode/text/28/2073","by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 2077","url":"https://www.law.cornell.edu/uscode/text/28/2077","subs":["(b)"],"by":{"0":"40"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)"],"stext":{"head":"§2342. Jurisdiction of court of appeals","paras":[[0,"The court of appeals (other than the United States Court of Appeals for the Federal Circuit) has exclusive jurisdiction to enjoin, set aside, suspend (in whole or in part), or to determine the validity of—"],[1,"(1) all final orders of the Federal Communication Commission made reviewable by section 402(a) of title 47;"],[1,"(2) all final orders of the Secretary of Agriculture made under chapters 9 and 20A of title 7, except orders issued under sections 210(e), 217a, and 499g(a) of title 7;"],[1,"(3) all rules, regulations, or final orders of—"],[2,"(A) the Secretary of Transportation issued pursuant to section 50501, 50502, 56101–56104, or 57109 of title 46 or pursuant to part B or C of subtitle IV, subchapter III of chapter 311, chapter 313, or chapter 315 of title 49; and"],[2,"(B) the Federal Maritime Commission issued pursuant to section 305,1 41304, 41308, or 41309 or chapter 421 or 441 of title 46;"],[1,"(4) all final orders of the Atomic Energy Commission made reviewable by section 2239 of title 42;"],[1,"(5) all rules, regulations, or final orders of the Surface Transportation Board made reviewable by section 2321 of this title;"],[1,"(6) all final orders under section 812 of the Fair Housing Act; and"],[1,"(7) all final agency actions described in section 20114(c) of title 49."],[0,"Jurisdiction is invoked by filing a petition as provided by section 2344 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2342?type=usc&year=mostrecent&link-type=html"},"head":"§2342. Jurisdiction of court of appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"14","3":"91"}},{"t":"reg","label":"47 C.F.R. pt. 54","url":"https://www.ecfr.gov/current/title-47/part-54","by":{"0":"4, 27","2":"37"}},{"t":"case","label":"Acheson Hotels, LLC v. Laufer","cite":"601 U.S. 1","y":2023,"id":"2023/22-429","sc":1,"sum":"Because Laufer voluntarily dismissed her pending suits under the Americans with Disabilities Act of 1990, Laufer’s case against Acheson is moot.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Collins v. Yellen","cite":"594 U.S. 220","y":2021,"id":"2020/19-422","sc":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"54"}},{"t":"case","label":"FCC v. Nat’l Citizens Comm. for Broad.","cite":"436 U.S. 775","y":1978,"id":"1977/76-1471","sc":1,"sum":"The challenged regulations are valid in their entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Fed. Radio Comm’n v. Nelson Bros. Bond & Mortg. Co.","cite":"289 U.S. 266","y":1933,"id":"scdb/1932-076","sc":1,"sum":"1. Congress can confer administrative authority on courts of the District of Columbia; but jurisdiction to review administrative ques tions can not be exercised by this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 34"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"op":8,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Jarkesy v. SEC","cite":"34 F.4th 446","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/34/446/","op":1,"sum":"Finding that Congress “unconstitutionally delegated legislative power to the SEC when . . . failing to provide it with an intelligible principle to guide its use of the delegated power”.","sumSrc":"brief:2","by":{"1":"15","2":"29"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"op":3,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"1":"31","2":"47"}},{"t":"case","label":"MCI Telecomms. Corp. v. Am. Tel. & Tel. Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"op":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"51, 52"}},{"t":"case","label":"Nat’l Ass’n Regul. Util. Comm’rs v. FCC","cite":"737 F.2d 1095","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/737/1095/","sum":"Rejecting argument that FCC had no authority over universal service because, in 47 U.S.C. § 151, “Congress directed that, ‘so far as possible, ... all people of the United States’ are to have adequate telephone facilities at reasonable prices”.","sumSrc":"brief:1","by":{"1":"3, 20, 32","5":"9, 15"}},{"t":"case","label":"Nevada Comm’n on Ethics v. Carrigan","cite":"564 U.S. 117","y":2011,"id":"2010/10-568","sc":1,"sum":"The Court held that the Nevada law requiring elected officials to disqualify themselves when they are asked to vote on matters that present a conflict of interest was constitutional.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Protestant Mem’l Med. Ctr., Inc. v. Maram","cite":"471 F.3d 724","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/471/724/","by":{"1":"19"}},{"t":"case","label":"Qwest Commc’ns Int’l, Inc. v. FCC","cite":"398 F.3d 1222","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/398/1222/","sum":"Finding no issue with the FCC’s proposed definition of “sufficient” to “includ[e] language intended to cap federal support at levels ‘only as large as necessary’ to meet the statutory goal”.","sumSrc":"brief:2","by":{"1":"26","2":"5, 22, 26, 34"}},{"t":"case","label":"Red Lion Broad. Co. v. FCC","cite":"395 U.S. 367","y":1969,"id":"1968/2","sc":1,"sum":"The Court held that the fairness doctrine was consistent with the First Amendment.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Seila Law LLC v. Consumer Fin. Prot. Bureau","cite":"591 U.S. 197","y":2020,"id":"2019/19-7","sc":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"1":"16, 51, 52","2":"12, 45, 46, 47, 48"}},{"t":"case","label":"United States v. Munsingwear, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Verizon Commc’ns v. FCC","cite":"535 U.S. 467","y":2002,"id":"2001/00-511","sc":1,"op":3,"sum":"The Court held that the FCC can require state commissions to set the rates charged by incumbents for leased elements on a forward-looking basis untied to the incumbents' investment and that the FCC can require incumbents to combine elements of their networks at the request of entrants.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Wayman v. Southard","cite":"23 U.S. 1","y":1825,"id":"scdb/1825-006","sc":1,"sum":"Wayman and another v. Southard and another.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"36","2":"27"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"usc","label":"47 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/47/153","subs":["(50)","(53)","(51)"],"stext":{"head":"§153. Definitions","paras":[[0,"For the purposes of this chapter, unless the context otherwise requires—"],[0,"(1) Advanced communications services"],[1,"The term \"advanced communications services\" means—"],[2,"(A) interconnected VoIP service;"],[2,"(B) non-interconnected VoIP service;"],[2,"(C) electronic messaging service;"],[2,"(D) interoperable video conferencing service; and"],[2,"(E) any audio or video communications service used by inmates for the purpose of communicating with individuals outside the correctional institution where the inmate is held, regardless of technology used."],[0,"(2) Affiliate"],[1,"The term \"affiliate\" means a person that (directly or indirectly) owns or controls, is owned or controlled by, or is under common ownership or control with, another person. For purposes of this paragraph, the term \"own\" means to own an equity interest (or the equivalent thereof) of more than 10 percent."],[0,"(3) Amateur station"],[1,"The term \"amateur station\" means a radio station operated by a duly authorized person interested in radio technique solely with a personal aim and without pecuniary interest."],[0,"(4) AT&T Consent Decree"],[1,"The term \"AT&T Consent Decree\" means the order entered August 24, 1982, in the antitrust action styled United States v. Western Electric, Civil Action No. 82–0192, in the United States District Court for the District of Columbia, and includes any judgment or order with respect to such action entered on or after August 24, 1982."],[0,"(5) Bell operating company"],[1,"The term \"Bell operating company\"—"],[2,"(A) means any of the following companies: Bell Telephone Company of Nevada, Illinois Bell Telephone Company, Indiana Bell Telephone Company, Incorporated, Michigan Bell Telephone Company, New England Telephone and Telegraph Company, New Jersey Bell Telephone Company, New York Telephone Company, U S West Communications Company, South Central Bell Telephone Company, Southern Bell Telephone and Telegraph Company, Southwestern Bell Telephone Company, The Bell Telephone Company of Pennsylvania, The Chesapeake and Potomac Telephone Company, The Chesapeake and Potomac Telephone Company of Maryland, The Chesapeake and Potomac Telephone Company of Virginia, The Chesapeake and Potomac Telephone Company of West Virginia, The Diamond State Telephone Company, The Ohio Bell Telephone Company, The Pacific Telephone and Telegraph Company, or Wisconsin Telephone Company; and"],[2,"(B) includes any successor or assign of any such company that provides wireline telephone exchange service; but"],[2,"(C) does not include an affiliate of any such company, other than an affiliate described in subparagraph (A) or (B)."],[0,"(6) Broadcast station"],[1,"The term \"broadcast station\", \"broadcasting station\", or \"radio broadcast station\" means a radio station equipped to engage in broadcasting as herein defined."],[0,"(7) Broadcasting"],[1,"The term \"broadcasting\" means the dissemination of radio communications intended to be received by the public, directly or by the intermediary of relay stations."],[0,"(8) Cable service"],[1,"The term \"cable service\" has the meaning given such term in section 522 of this title."],[0,"(9) Cable system"],[1,"The term \"cable system\" has the meaning given such term in section 522 of this title."],[0,"(10) Chain broadcasting"],[1,"The term \"chain broadcasting\" means simultaneous broadcasting of an identical program by two or more connected stations."],[0,"(11) Common carrier"],[1,"The term \"common carrier\" or \"carrier\" means any person engaged as a common carrier for hire, in interstate or foreign communication by wire or radio or interstate or foreign radio transmission of energy, except where reference is made to common carriers not subject to this chapter; but a person engaged in radio broadcasting shall not, insofar as such person is so engaged, be deemed a common carrier."],[0,"(12) Connecting carrier"],[1,"The term \"connecting carrier\" means a carrier described in clauses (2), (3), or (4) of section 152(b) of this title."],[0,"(13) Construction permit"],[1,"The term \"construction permit\" or \"permit for construction\" means that instrument of authorization required by this chapter or the rules and regulations of the Commission made pursuant to this chapter for the construction of a station, or the installation of apparatus, for the transmission of energy, or communications, or signals by radio, by whatever name the instrument may be designated by the Commission."],[0,"(14) Consumer generated media"],[1,"The term \"consumer generated media\" means content created and made available by consumers to online websites and services on the Internet, including video, audio, and multimedia content."],[0,"(15) Corporation"],[1,"The term \"corporation\" includes any corporation, joint-stock company, or association."],[0,"(16) Customer premises equipment"],[1,"The term \"customer premises equipment\" means equipment employed on the premises of a person (other than a carrier) to originate, route, or terminate telecommunications."],[0,"(17) Dialing parity"],[1,"The term \"dialing parity\" means that a person that is not an affiliate of a local exchange carrier is able to provide telecommunications services in such a manner that customers have the ability to route automatically, without the use of any access code, their telecommunications to the telecommunications services provider of the customer's designation from among 2 or more telecommunications services providers (including such local exchange carrier)."],[0,"(18) Disability"],[1,"The term \"disability\" has the meaning given such term under section 12102 of title 42."],[0,"(19) Electronic messaging service"],[1,"The term \"electronic messaging service\" means a service that provides real-time or near real-time non-voice messages in text form between individuals over communications networks."],[0,"(20) Exchange access"],[1,"The term \"exchange access\" means the offering of access to telephone exchange services or facilities for the purpose of the origination or termination of telephone toll services."],[0,"(21) Foreign communication"],[1,"The term \"foreign communication\" or \"foreign transmission\" means communication or transmission from or to any place in the United States to or from a foreign country, or between a station in the United States and a mobile station located outside the United States."],[0,"(22) Great Lakes Agreement"],[1,"The term \"Great Lakes Agreement\" means the Agreement for the Promotion of Safety on the Great Lakes by Means of Radio in force and the regulations referred to therein."],[0,"(23) Harbor"],[1,"The term \"harbor\" or \"port\" means any place to which ships may resort for shelter or to load or unload passengers or goods, or to obtain fuel, water, or supplies. This term shall apply to such places whether proclaimed public or not and whether natural or artificial."],[0,"(24) Information service"],[1,"The term \"information service\" means the offering of a capability for generating, acquiring, storing, transforming, processing, retrieving, utilizing, or making available information via telecommunications, and includes electronic publishing, but does not include any use of any such capability for the management, control, or operation of a telecommunications system or the management of a telecommunications service."],[0,"(25) Interconnected VoIP service"],[1,"The term \"interconnected VoIP service\" has the meaning given such term under section 9.3 of title 47, Code of Federal Regulations, as such section may be amended from time to time."],[0,"(26) InterLATA service"],[1,"The term \"interLATA service\" means telecommunications between a point located in a local access and transport area and a point located outside such area."],[0,"(27) Interoperable video conferencing service"],[1,"The term \"interoperable video conferencing service\" means a service that provides real-time video communications, including audio, to enable users to share information of the user's choosing."],[0,"(28) Interstate communication"],[1,"The term \"interstate communication\" or \"interstate transmission\" means communication or transmission (A) from any State, Territory, or possession of the United States (other than the Canal Zone), or the District of Columbia, to any other State, Territory, or possession of the United States (other than the Canal Zone), or the District of Columbia, (B) from or to the United States to or from the Canal Zone, insofar as such communication or transmission takes place within the United States, or (C) between points within the United States but through a foreign country; but shall not, with respect to the provisions of subchapter II of this chapter (other than section 223 of this title), include wire or radio communication between points in the same State, Territory, or possession of the United States, or the District of Columbia, through any place outside thereof, if such communication is regulated by a State commission."],[0,"(29) Land station"],[1,"The term \"land station\" means a station, other than a mobile station, used for radio communication with mobile stations."],[0,"(30) Licensee"],[1,"The term \"licensee\" means the holder of a radio station license granted or continued in force under authority of this chapter."],[0,"(31) Local access and transport area"],[1,"The term \"local access and transport area\" or \"LATA\" means a contiguous geographic area—"],[2,"(A) established before February 8, 1996, by a Bell operating company such that no exchange area includes points within more than 1 metropolitan statistical area, consolidated metropolitan statistical area, or State, except as expressly permitted under the AT&T Consent Decree; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/153?type=usc&year=mostrecent&link-type=html"},"head":"§153. Definitions","tname":"Telecommunications","by":{"1":"21, 21, 27","5":"17, 17"}},{"t":"usc","label":"47 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/47/201","subs":["(b)"],"stext":{"head":"§201. Service and charges","paras":[[0,"(a) It shall be the duty of every common carrier engaged in interstate or foreign communication by wire or radio to furnish such communication service upon reasonable request therefor; and, in accordance with the orders of the Commission, in cases where the Commission, after opportunity for hearing, finds such action necessary or desirable in the public interest, to establish physical connections with other carriers, to establish through routes and charges applicable thereto and the divisions of such charges, and to establish and provide facilities and regulations for operating such through routes."],[0,"(b) All charges, practices, classifications, and regulations for and in connection with such communication service, shall be just and reasonable, and any such charge, practice, classification, or regulation that is unjust or unreasonable is declared to be unlawful: Provided, That communications by wire or radio subject to this chapter may be classified into day, night, repeated, unrepeated, letter, commercial, press, Government, and such other classes as the Commission may decide to be just and reasonable, and different charges may be made for the different classes of communications: Provided further, That nothing in this chapter or in any other provision of law shall be construed to prevent a common carrier subject to this chapter from entering into or operating under any contract with any common carrier not subject to this chapter, for the exchange of their services, if the Commission is of the opinion that such contract is not contrary to the public interest: Provided further, That nothing in this chapter or in any other provision of law shall prevent a common carrier subject to this chapter from furnishing reports of positions of ships at sea to newspapers of general circulation, either at a nominal charge or without charge, provided the name of such common carrier is displayed along with such ship position reports. The Commission may prescribe such rules and regulations as may be necessary in the public interest to carry out the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§201. Service and charges","tname":"Telecommunications","by":{"1":"20, 47"}},{"t":"usc","label":"47 U.S.C. § 205","url":"https://www.law.cornell.edu/uscode/text/47/205","by":{"1":"20"}},{"t":"usc","label":"47 U.S.C. § 252","url":"https://www.law.cornell.edu/uscode/text/47/252","subs":["(d)(1)"],"by":{"1":"29"}},{"t":"usc","label":"47 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/47/307","subs":["(a)","(d)"],"by":{"1":"32, 32"}},{"t":"usc","label":"47 U.S.C. § 309","url":"https://www.law.cornell.edu/uscode/text/47/309","subs":["(a)"],"by":{"1":"32"}},{"t":"usc","label":"47 U.S.C. § 310","url":"https://www.law.cornell.edu/uscode/text/47/310","by":{"1":"32"}},{"t":"usc","label":"47 U.S.C. § 312","url":"https://www.law.cornell.edu/uscode/text/47/312","by":{"1":"32"}},{"t":"usc","label":"47 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/47/1302","subs":["(b)"],"by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 111-5","url":"https://www.govinfo.gov/link/plaw/111/public/5","by":{"1":"7, 13"}},{"t":"law","label":"Pub. L. No. 105-119","url":"https://www.govinfo.gov/link/plaw/105/public/119","by":{"1":"7"}},{"t":"law","label":"Infrastructure Investment and Jobs Act, Pub. L. No. 117-58","url":"https://www.govinfo.gov/link/plaw/117/public/58","by":{"1":"8, 22, 25","3":"15"}},{"t":"reg","label":"47 C.F.R. § 54.410","url":"https://www.ecfr.gov/current/title-47/section-54.410","by":{"1":"41"}},{"t":"reg","label":"47 C.F.R. § 54.500","url":"https://www.ecfr.gov/current/title-47/section-54.500","by":{"1":"37","5":"20"}},{"t":"reg","label":"47 C.F.R. § 54.507","url":"https://www.ecfr.gov/current/title-47/section-54.507","subs":["(a)"],"by":{"1":"41","2":"38"}},{"t":"reg","label":"47 C.F.R. § 54.511","url":"https://www.ecfr.gov/current/title-47/section-54.511","subs":["(b)"],"by":{"1":"37"}},{"t":"reg","label":"47 C.F.R. § 54.603","url":"https://www.ecfr.gov/current/title-47/section-54.603","by":{"1":"37"}},{"t":"reg","label":"47 C.F.R. § 54.604","url":"https://www.ecfr.gov/current/title-47/section-54.604","by":{"1":"37, 41"}},{"t":"reg","label":"47 C.F.R. § 54.605","url":"https://www.ecfr.gov/current/title-47/section-54.605","by":{"1":"37, 41"}},{"t":"reg","label":"47 C.F.R. § 54.606","url":"https://www.ecfr.gov/current/title-47/section-54.606","by":{"1":"41"}},{"t":"reg","label":"47 C.F.R. § 54.622","url":"https://www.ecfr.gov/current/title-47/section-54.622","by":{"1":"46"}},{"t":"reg","label":"47 C.F.R. § 54.702","url":"https://www.ecfr.gov/current/title-47/section-54.702","subs":["(b)","(c)","(g)","(h)","(j)","(k)"],"by":{"1":"10, 10, 41, 10, 43, 10, 43, 10, 43, 10","2":"7, 36","5":"20"}},{"t":"reg","label":"47 C.F.R. § 54.706","url":"https://www.ecfr.gov/current/title-47/section-54.706","subs":["(a)","(e)"],"by":{"1":"21","2":"6, 7","3":"9, 58"}},{"t":"reg","label":"47 C.F.R. § 54.709","url":"https://www.ecfr.gov/current/title-47/section-54.709","subs":["(a)(2)","(a)(3)","(b)","(a)","(c)"],"by":{"1":"10, 41, 42, 11, 12, 41, 42, 44, 45, 43","2":"6, 35, 6, 36, 9, 36, 8, 9, 36, 7","3":"9, 10, 16, 75","4":"16, 17, 16, 17","5":"18, 18, 21"}},{"t":"reg","label":"47 C.F.R. § 54.711","url":"https://www.ecfr.gov/current/title-47/section-54.711","subs":["(a)"],"by":{"1":"42","2":"6"}},{"t":"reg","label":"47 C.F.R. § 54.717","url":"https://www.ecfr.gov/current/title-47/section-54.717","by":{"1":"47"}},{"t":"reg","label":"47 C.F.R. § 54.719","url":"https://www.ecfr.gov/current/title-47/section-54.719","by":{"1":"43","2":"7"}},{"t":"reg","label":"47 C.F.R. § 54.723","url":"https://www.ecfr.gov/current/title-47/section-54.723","by":{"1":"43","5":"21"}},{"t":"reg","label":"47 C.F.R. § 54.801","url":"https://www.ecfr.gov/current/title-47/section-54.801","by":{"1":"47","2":"8, 38"}},{"t":"reg","label":"47 C.F.R. § 54.802","url":"https://www.ecfr.gov/current/title-47/section-54.802","by":{"1":"47"}},{"t":"reg","label":"47 C.F.R. § 54.803","url":"https://www.ecfr.gov/current/title-47/section-54.803","by":{"1":"47","4":"20"}},{"t":"reg","label":"47 C.F.R. § 54.804","url":"https://www.ecfr.gov/current/title-47/section-54.804","by":{"1":"47"}},{"t":"reg","label":"47 C.F.R. § 54.805","url":"https://www.ecfr.gov/current/title-47/section-54.805","subs":["(a)"],"by":{"1":"47","2":"8, 38","3":"78","4":"20, 19"}},{"t":"reg","label":"47 C.F.R. § 54.806","url":"https://www.ecfr.gov/current/title-47/section-54.806","by":{"1":"47"}},{"t":"reg","label":"Administrative Materials Access Charges; MTS and WATS Market Structure, 48 Fed. Reg. 1031","url":"https://www.govinfo.gov/link/fr/48/1031","by":{"1":"3"}},{"t":"reg","label":"MTS and WATS Market Structure, 51 Fed. Reg. 1371","url":"https://www.govinfo.gov/link/fr/51/1371","by":{"1":"3"}},{"t":"reg","label":"MTS and WATS Market Structure; and Establishment of a Joint Board; Amendment, 50 Fed. Reg. 939","url":"https://www.govinfo.gov/link/fr/50/939","by":{"1":"3"}},{"t":"case","label":"Boerschig v. Trans-Pecos Pipeline, LLC","cite":"872 F.3d 701","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/872/701/","by":{"2":"35"}},{"t":"case","label":"Burt v. Titlow","cite":"571 U.S. 12","y":2013,"id":"2013/12-414","sc":1,"sum":"The Court held that the Antiterrorism and Effective Death Penalty Act requires the Court of Appeals to apply a “doubly-deferential” standard in which both the state court and the defense attorney are given the benefit of the doubt in murder cases.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"City of Los Angeles v. Patel","cite":"576 U.S. 409","y":2015,"id":"2014/13-1175","sc":1,"sum":"The Court determined that a municipal ordinance that allows the police to inspect hotel records without a warrant violates the Fourth Amendment’s prohibition against unreasonable searches unless the business owner is given the opportunity for pre-compliance review.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Consumers’ Rsch. v. FCC","cite":"2023 WL 3807406","y":2023,"court":"6th Cir. May 30","by":{"2":"9"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"41"}},{"t":"case","label":"FCC v. Schreiber","cite":"381 U.S. 279","y":1965,"id":"1964/482","sc":1,"op":1,"sum":"To secure comprehensive information about various practices in the television industry, the Federal Communications Commission initiated an investigatory proceeding pursuant to § 403 of the Communications Act. The Presiding Officer, assigned to conduct the proceeding, was authorized by the Commission to subpoena witnesses and to compel the production of any records or documents deemed relevant. The proceedings were …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"sum":"1. Antipicketing ordinance, virtually identical with one invalidated as violative of equal protection in Police Department of Chicago v. Mosley, ante, p. 92, is likewise invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Harris v. Arizona Indep. Redistricting Comm’n","cite":"578 U.S. 253","y":2016,"id":"2015/14-232","sc":1,"sum":"The Court determined that the creation of voting districts that deviate from the “one person, one vote” principle may be justified by legitimate considerations, such as a desire to comply with the Voting Rights Act as it was in effect at the time of the plan.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Heien v. North Carolina","cite":"574 U.S. 54","y":2014,"id":"2014/13-604","sc":1,"sum":"The Court decided that search and seizures are acceptable if a police officer made a reasonable factual or legal mistake.","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"Huawei Techs. USA, Inc. v. FCC","cite":"2 F.4th 421","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/2/421/","sum":"Finding a lack of support for the argument that the FCC “may deploy the universal-service mechanism to accomplish any non-prohibited purpose in the Act”.","sumSrc":"brief:2","by":{"2":"5–6"}},{"t":"case","label":"Indus. Union Dep’t, AFL-CIO v. Am. Petroleum Inst.","cite":"448 U.S. 607","y":1980,"id":"1979/78-911","sc":1,"op":7,"sum":"The Court agreed with the Court of Appeals that the Secretary had acted without knowledge that the new standard was necessary to \"provide safe and healthful employment\" as mandated by the Act. Nothing in OSHA's administrative record indicated that exposure to benzene at 10 ppm would cause leukemia and that exposure to one ppm would not.","sumSrc":"Oyez","by":{"2":"29","3":"5"}},{"t":"case","label":"Jacobellis v. State of Ohio","cite":"378 U.S. 184","y":1964,"id":"1963/11","sc":1,"sum":"The judgment is reversed. Pp. 184-198. 173 Ohio St. 22, 179 N. E. 2d 777, reversed. MR. JUSTIcE BRENNAN, joined by MR. JUSTIcE GOLDBERG, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48"}},{"t":"case","label":"Kirk v. Comm’r of Soc. Sec. Admin.","cite":"987 F.3d 314","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/987/314/","sum":"Finding that the Social Security Administration violated due process by denying the opportunity to contest fraud allegations.","sumSrc":"brief:2","by":{"2":"44"}},{"t":"case","label":"L.D.G. v. Holder","cite":"744 F.3d 1022","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/744/1022/","op":1,"by":{"2":"29"}},{"t":"case","label":"Nat’l Cable Television Ass’n, Inc. v. United States","cite":"415 U.S. 336","y":1974,"url":"https://supreme.justia.com/cases/federal/us/415/336/","sc":1,"op":9,"sum":"Interpreting the Independent Offices Appropriation Act “narrowly to avoid constitutional problems” with the intelligible principle test.","sumSrc":"brief:2","by":{"2":"29","3":"20, 28, 67, 69"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"2":"53"}},{"t":"case","label":"Pension Ben. Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Rural Cellular Ass’n v. FCC","cite":"588 F.3d 1095","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/588/1095/","op":1,"by":{"2":"25"}},{"t":"case","label":"Rural Tel. Coal. v. FCC","cite":"838 F.2d 1307","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/838/1307/","op":1,"by":{"2":"3"}},{"t":"case","label":"Samia v. United States","cite":"599 U.S. 635","y":2023,"id":"2022/22-196","sc":1,"sum":"The admission of a nontestifying codefendant’s confession did not violate the Sixth Amendment’s Confrontation Clause where the confession as modified did not directly inculpate the defendant but used the descriptor “other person” and the jury was instructed to consider the confession only as to the codefendant.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"41"}},{"t":"case","label":"State v. Rettig","cite":"987 F.3d 518","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/987/518/","by":{"2":"42"}},{"t":"case","label":"Tex. Off. of Pub. Util. Couns. v. FCC","cite":"265 F.3d 313","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/265/313/","by":{"2":"4","3":"7, 47, 49, 50, 75","5":"8"}},{"t":"case","label":"United States v. AT&T","cite":"552 F. Supp. 131","y":1982,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./552/131/","by":{"2":"3"}},{"t":"case","label":"Vonage Holdings Corp. v. FCC","cite":"489 F.3d 1232","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/489/1232/","by":{"2":"25"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"2":"41"}},{"t":"case","label":"West Virginia v. Env’t Prot. Agency","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"op":5,"by":{"2":"30"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(13)"],"by":{"2":"42"}},{"t":"usc","label":"34 U.S.C. § 20913","url":"https://www.law.cornell.edu/uscode/text/34/20913","subs":["(d)"],"by":{"2":"31"}},{"t":"reg","label":"47 C.F.R. § 54.403","url":"https://www.ecfr.gov/current/title-47/section-54.403","by":{"2":"38, 8, 39"}},{"t":"reg","label":"47 C.F.R. § 54.407","url":"https://www.ecfr.gov/current/title-47/section-54.407","by":{"2":"8, 38, 8","3":"10"}},{"t":"reg","label":"47 C.F.R. § 54.409","url":"https://www.ecfr.gov/current/title-47/section-54.409","by":{"2":"38, 8, 39"}},{"t":"reg","label":"47 C.F.R. § 54.619","url":"https://www.ecfr.gov/current/title-47/section-54.619","by":{"2":"39"}},{"t":"reg","label":"47 C.F.R. § 54.701","url":"https://www.ecfr.gov/current/title-47/section-54.701","by":{"2":"7, 7","3":"8"}},{"t":"reg","label":"47 C.F.R. § 54.722","url":"https://www.ecfr.gov/current/title-47/section-54.722","by":{"2":"7"}},{"t":"reg","label":"47 C.F.R. § 54.901","url":"https://www.ecfr.gov/current/title-47/section-54.901","by":{"2":"38"}},{"t":"const","label":"Article I","by":{"2":"15, 28","3":"19, 23"}},{"t":"case","label":"Nathan v. Louisiana","cite":"49 U.S. 73","y":1850,"id":"scdb/1850-006","sc":1,"sum":"A tax imposed by a State upon all money or exchange brokers is not void for repugnance to the constitutional power of Congress to regulate commerce.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"1, 31"}},{"t":"case","label":"Airlines for Am., Inc. v. DOT, ___ F.4th ___","cite":"2025 WL 313998","y":2025,"court":"5th Cir. Jan. 28","by":{"3":"64"}},{"t":"case","label":"Ass’n of Am. Railroads v. DOT","cite":"721 F.3d 666","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/721/666/","by":{"3":"79"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"op":2,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"61"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"91"}},{"t":"case","label":"Bridas SAPIC v. Turkmenistan","cite":"345 F.3d 347","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/345/347/","by":{"3":"73"}},{"t":"case","label":"Brock v. Roadway Express, Inc.","cite":"481 U.S. 252","y":1987,"id":"1986/85-1530","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 624 F. Supp. 197, affirmed in part and reversed in part. JUSTICE MARSHALL, joined by JUSTICE BLACKMUN, JUSTICE POWELL, and JUSTICE O'CONNOR, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"93"}},{"t":"case","label":"Brown v. Chote","cite":"411 U.S. 452","y":1973,"id":"1972/71-1583","sc":1,"sum":"Given the possibility that appellee would prevail on the merits and the fact that appellee's opportunity to be a candidate would have been foreclosed, absent, interim relief, the District Court did not abuse its discretion in granting a preliminary injunction. Pp. 456-457. 342 F. Supp. 1353, affirmed and remanded.' BURGER, C. J., delivered the opinion for a unanimous Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"94"}},{"t":"case","label":"Burlington N. R.R. Co. v. Bhd. of Maint. of Way Emps.","cite":"481 U.S. 429","y":1987,"id":"1986/86-39","sc":1,"sum":"The Court held that Congress passed the Norris-LaGuardia Act expressly to prevent courts from distinguishing between primary and secondary actors for the purposes of labor immunity in labor disputes.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Cal. Coastal Comm’n v. Granite Rock Co.","cite":"480 U.S. 572","y":1987,"id":"1986/85-1200","sc":1,"sum":"The Mining Act of 1872 authorizes a private citizen to enter federal lands to explore for mineral deposits, to perfect a mining claim, and to secure a patent to the land by complying with the requirements of the Act and regulations promulgated thereunder. Appellee Granite Rock Co. holds unpatented mining claims on federally owned lands in a national forest located in California. In accordance with federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"93"}},{"t":"case","label":"Carroll v. President & Comm’rs of Princess Anne","cite":"393 U.S. 175","y":1968,"id":"1968/6","sc":1,"sum":"The Supreme Court held that the case was not moot because the 10-day order still plays a role in the white supremacist organization's continued efforts in the county. The order was set aside because there was no notice given to the organization and they were not given the opportunity to participate in the adversary proceeding.","sumSrc":"Oyez","by":{"3":"94"}},{"t":"case","label":"CFPB v. Law Offs. of Crystal Moroney, P.C.","cite":"63 F.4th 174","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/63/174/","sum":"Finding the statutory “twelve-percent limit on the amount of funding [the CFPB] may draw from the Federal Reserve System” “clearly delineates the … boundaries of this delegated budgetary authority”.","sumSrc":"brief:3","by":{"3":"67"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"3":"76"}},{"t":"case","label":"City of Springfield v. Ostrander (In re LAN Tamers, Inc.)","cite":"329 F.3d 204","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/329/204/","by":{"3":"7"}},{"t":"case","label":"Davis v. FEC","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"3":"91, 93"}},{"t":"case","label":"Democratic Party of U.S. v. Wis. ex rel. La Follette","cite":"450 U.S. 107","y":1981,"id":"1980/79-1631","sc":1,"sum":"Referring to its decision in Cousins v. Wigoda , the Court held that the \"First Amendment freedom to gather in association for the purpose of advancing shared beliefs is protected by the Fourteenth Amendment from infringement by any State.\" Granting states the power to place delegates in a National Convention over party objections to how they were selected would impair the right of political parties to associate with whom they wish, especially when non-party members could influence the interests of the delegates.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Does 1–3 v. Mills","cite":"142 S. Ct. 17","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./142/17/","sc":1,"op":1,"ar":3,"by":{"3":"80, 95"}},{"t":"case","label":"DOT v. Ass’n of Am. Railroads","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"op":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"3":"40, 42, 69, 74, 76, 85, 88"}},{"t":"case","label":"Dunn v. Blumstein","cite":"405 U.S. 330","y":1972,"id":"1971/70-13","sc":1,"sum":"In a 6-to-1 decision, the Court held that the law was an unconstitutional infringement upon the right to vote and the right to travel. Applying a strict equal protection test, the Court found that the law did not necessarily promote a compelling state interest.","sumSrc":"Oyez","by":{"3":"94"}},{"t":"case","label":"Empower Texans, Inc. v. Geren","cite":"977 F.3d 367","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/367/","by":{"3":"96"}},{"t":"case","label":"FEC v. Wis. Right to Life, Inc.","cite":"551 U.S. 449","y":2007,"id":"2006/06-969","sc":1,"ar":9,"sum":"By a 5-4 vote the Court ruled that BCRA's limitations on political advertising were unconstitutional as they applied to issue ads like WRTL's. Chief Justice John Roberts's majority opinion held that the ads were genuine issue ads, not express political advocacy or its functional equivalent (which Congress can concededly regulate).","sumSrc":"Oyez","by":{"3":"91, 93"}},{"t":"case","label":"First Nat’l Bank of Bos. v. Bellotti","cite":"435 U.S. 765","y":1978,"id":"1977/76-1172","sc":1,"op":10,"ar":2,"sum":"The Court held that the right to attempt to influence the outcomes of elections is one of the primary rights the First Amendment was meant to protect. If this form of speech came from a person rather than a corporation, there would be no question about whether it was protected speech.","sumSrc":"Oyez","by":{"3":"54, 61, 84, 91, 92, 93, 95"}},{"t":"case","label":"Gaines v. Thompson","cite":"74 U.S. 347","y":1868,"id":"scdb/1868-009","sc":1,"sum":"The Secretary of the Interior having directed the Commissioner of the Land Office to cancel an entry under which Gaines and others.claimed an equitable right to certain lands _in Arkansas, these last brought their suit in the Circuit Court of the District of Columbia, praying that the secretary and commissioner should be enjoined from making such cancellation. The defendants entered their appearance, and Wilson, the …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"77"}},{"t":"case","label":"Gannett Co. v. DePasquale","cite":"443 U.S. 368","y":1979,"id":"1978/77-1301","sc":1,"sum":"The Court held that members of the public had no right to attend criminal trials under the Sixth and Fourteenth Amendments. The Court noted that judges had \"an affirmative constitutional duty\" to minimize the effects of prejudicial pretrial publicity, and that closure of pretrial proceedings was an effective method to do so.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Globe Newspaper Co. v. Superior Ct. for Norfolk Cnty.","cite":"457 U.S. 596","y":1982,"id":"1981/81-611","sc":1,"sum":"The Court held that the Massachusetts law violated the First Amendment. Recalling the Court's holding in Richmond Newspapers v. Virginia (1980), Justice Brennan reviewed important historical and judicial reasons why access to criminal trials is \"properly afforded\" First Amendment protection. When the court denies access, argued Brennan, the only justification is to serve a compelling state interest.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Honig v. Doe","cite":"484 U.S. 305","y":1988,"id":"1987/86-728","sc":1,"sum":"The Supreme Court, in an opinion by Justice William J. Brennan, held that since the Act covered individuals from ages 3 to 21, the claim of a 24-year-old who was no longer in school was moot, but that the claim of a 20-year-old was not moot.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"3":"79"}},{"t":"case","label":"Mayfield v. DOL","cite":"117 F.4th 611","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/117/611/","ar":1,"by":{"3":"64"}},{"t":"case","label":"Memphis Light, Gas & Water Div. v. Craft","cite":"436 U.S. 1","y":1978,"id":"1977/76-39","sc":1,"sum":"Because of two separate sets of gas and electric meters in their newly purchased house, respondents, for about a year after moving in, received separate monthly bills for each set of meters from a municipal utility. During this period respondents' utility service was terminated five times for nonpayment of bills. Despite respondent wife's good-faith efforts to determine the cause of the \"double billing,\" she was …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"90"}},{"t":"case","label":"Meyer v. Grant","cite":"486 U.S. 414","y":1988,"id":"1987/87-920","sc":1,"sum":"The statutory prohibition against the use of paid circulators abridges appellees' right to engage in political speech in violation of the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"93"}},{"t":"case","label":"Moore v. United States","cite":"602 U.S. 572","y":2024,"id":"2023/22-800","sc":1,"op":1,"sum":"The Mandatory Repatriation Tax—which attributes the realized and undistributed income of an American-controlled foreign corporation to the entity’s American shareholders, and then taxes the American shareholders on their portions of that income—does not exceed Congress’s constitutional authority.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22"}},{"t":"case","label":"Morse v. Republican Party of Va.","cite":"517 U.S. 186","y":1996,"id":"1995/94-203","sc":1,"op":2,"sum":"Yes and yes.","sumSrc":"Oyez","by":{"3":"90, 93"}},{"t":"case","label":"N. Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"3":"63"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"3":"26"}},{"t":"case","label":"Ne. Fla. Chapter of Associated Gen. Contractors of Am. v. City of Jacksonville","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"sum":"The majority determined that the association members' possible lack of fair opportunity as a consequence of the ordinance would have constituted injury. Since the association members would have competed for the reserved city contracts in the absence of the ordinance, the Court found that they did have standing and reversed the judgment of the Court of Appeals.","sumSrc":"Oyez","by":{"3":"92"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Norman v. Reed","cite":"502 U.S. 279","y":1992,"id":"1991/90-1126","sc":1,"sum":"Illinois citizens wishing to establish a \"new political party\" may field candidates for statewide office after collecting the signatures of 25,000 eligible voters, and they may field candidates solely for offices in a large \"political subdivision\" upon collecting the signatures of 25,000 subdivision voters. Ill. Rev. Stat., ch. 46, § 10-2. However, when a subdivision comprises large separate districts from which …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"93"}},{"t":"case","label":"Olmstead v. L.C. ex rel. Zimring","cite":"527 U.S. 581","y":1999,"id":"1998/98-536","sc":1,"sum":"The Court then found that the ADA required the placement of patients with mental disabilities in \"integrated settings\" when they are medically cleared for such settings, they themselves express a desire for such settings, and the resources for such a transfer are available.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Paul v. United States","cite":"140 S. Ct. 342","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./140/342/","sc":1,"op":1,"by":{"3":"30, 61"}},{"t":"case","label":"Press-Enter. Co. v. Superior Ct. of Cal. for Riverside Cnty.","cite":"478 U.S. 1","y":1986,"id":"1985/84-1560","sc":1,"sum":"The Supreme Court held that the First Amendment right of public access applies to preliminary hearings. Closed preliminary hearings are only permissible when specific findings on the record show that closure is essential.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Richmond Newspapers, Inc. v. Virginia","cite":"448 U.S. 555","y":1980,"id":"1979/79-243","sc":1,"op":5,"sum":"In a 7-to-1 decision, the Court held that the right to attend criminal trials was \"implicit in the guarantees of the First Amendment.\" The Court held that the First Amendment encompassed not only the right to speak but also the freedom to listen and to receive information and ideas. The Court also noted that the First Amendment guaranteed the right of assembly in public places such as courthouses.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Rosario v. Rockefeller","cite":"410 U.S. 752","y":1973,"id":"1972/71-1371","sc":1,"sum":"New York's delayed-enrollment scheme did not violate petitioners' constitutional rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"94"}},{"t":"case","label":"Sandwich Isles Commc’ns, Inc. v. United States","cite":"992 F.3d 1355","y":2021,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/992/1355/","by":{"3":"91"}},{"t":"case","label":"Sapp v. Renfroe","cite":"511 F.2d 172","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/511/172/","by":{"3":"90"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"591 U.S. 197","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/197/","sc":1,"by":{"3":"2, 59"}},{"t":"case","label":"U.S. ex rel. Shupe v. Cisco Sys., Inc.","cite":"759 F.3d 379","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/759/379/","by":{"3":"74"}},{"t":"case","label":"Spencer v. Kemna","cite":"523 U.S. 1","y":1998,"id":"1997/96-7171","sc":1,"sum":"The Court held that the expiration of Spencer's sentence caused his petition to be moot because it no longer presented an Article III case or controversy. The Court concluded that once a petitioner's sentence has expired he must demonstrate a concrete and continuing injury to maintain suit.","sumSrc":"Oyez","by":{"3":"92, 93"}},{"t":"case","label":"Storer v. Brown","cite":"415 U.S. 724","y":1974,"id":"1973/72-812","sc":1,"op":7,"sum":"Section 6830 (d) (Supp. 1974) of the California Elections Code forbids ballot position to hn independent candidate for-elective public office if he had a registered affiliation with a qualified political party within one year prior to the immediately preceding primary election; § 3831 (1961) requires an independent candidate's nominating papers to be signed by voters not less in number than 5% nor more than 6% of …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"94"}},{"t":"case","label":"Super Tire Eng’g Co. v. McCorkle","cite":"416 U.S. 115","y":1974,"id":"1973/72-1554","sc":1,"sum":"To the extent that declaratoryrelief was sought, the case-or-controversy requirement of Art. III, § 2, and the Declaratory Judgment Act is completely satisfied. -","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"94"}},{"t":"case","label":"Texas v. Rettig","cite":"993 F.3d 408","y":2021,"url":"https://www.courtlistener.com/c/F.3d/993/408/","by":{"3":"84"}},{"t":"case","label":"Trafigura Trading LLC v. United States","cite":"29 F.4th 286","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/29/286/","by":{"3":"27"}},{"t":"case","label":"Turner v. Rogers","cite":"564 U.S. 431","y":2011,"id":"2010/10-10","sc":1,"sum":"The Court held that a defendant facing incarceration for civil contempt does not have a constitutional right to a court-appointed attorney under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"U.S. Dep’t of Navy v. FLRA","cite":"665 F.3d 1339","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1339/","by":{"3":"24"}},{"t":"case","label":"U.S. Telecom Ass’n v. FCC","cite":"359 F.3d 554","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/359/554/","by":{"3":"76, 85"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"op":2,"sum":"The Court held that the President has greater legislative power in international affairs than would be allowed in domestic ones.","sumSrc":"Oyez","by":{"3":"40, 41, 42"}},{"t":"case","label":"United States v. Mazurie","cite":"419 U.S. 544","y":1975,"id":"1974/73-1018","sc":1,"sum":"Respondents, who operated a bar on non-Indian land on the outskirts of an unincorporated village within the Wind River Reservation and who had been denied a tribal liquor license by the Wind River Tribes pursuant to their option under 18 U. S. C. § 1161 to regulate the introduction of liquor into Indian country, were convicted at a nonjury trial of introducing spirituous beverages into Indian country in violation of …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"40, 42, 68"}},{"t":"case","label":"United States v. N.Y. Tel. Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"sum":"On the basis of an FBI affidavit stating that certain individuals were conducting an illegal gambling enterprise at a specified New York City address and that there was probable cause to believe that two telephones with different numbers were being used there to further the illegal activity, the District Court authorized the FBI to install and use pen registers with respect to the two telephones, and directed …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"94, 95"}},{"t":"case","label":"United States v. U.S. Shoe Corp.","cite":"523 U.S. 360","y":1998,"id":"1997/97-372","sc":1,"op":1,"sum":"The Court held that \"the [Harbor Maintenance Tax], which is imposed on an ad valorem basis, is not a fair approximation of services, facilities, or benefits furnished to the exporters, and therefore does not qualify as a permissible user fee.\" The Court noted that the Export Clause does not categorically bar Congress from imposing any tax on exports and that a charge designed as compensation for government-supplied services, facilities, or benefits would pass scrutiny.","sumSrc":"Oyez","by":{"3":"27"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"3":"93"}},{"t":"case","label":"Veazie Bank v. Fenno","cite":"75 U.S. 533","y":1869,"id":"scdb/1869-154","sc":1,"op":1,"sum":"The Constitution ordains that:","sumSrc":"Headnote (U.S. Reports)","by":{"3":"34"}},{"t":"case","label":"Wis. Dept. of Indus., Lab., & Hum. Rels. v. Gould Inc.","cite":"475 U.S. 282","y":1986,"id":"1985/84-1484","sc":1,"op":4,"sum":"The NLRA pre-empts the Wisconsin debarment statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"93"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"3":"76"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"3":"76"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"3":"76"}},{"t":"usc","label":"8 U.S.C. § 1356","url":"https://www.law.cornell.edu/uscode/text/8/1356","by":{"3":"39"}},{"t":"usc","label":"12 U.S.C. § 243","url":"https://www.law.cornell.edu/uscode/text/12/243","stext":{"head":"§243. Assessments upon Federal reserve banks to pay expenses","paras":[[0,"The Board of Governors of the Federal Reserve System shall have power to levy semiannually upon the Federal reserve banks, in proportion to their capital stock and surplus, an assessment sufficient to pay its estimated expenses and the salaries of its members and employees for the half year succeeding the levying of such assessment, together with any deficit carried forward from the preceding half year, and such assessments may include amounts sufficient to provide for the acquisition by the Board in its own name of such site or building in the District of Columbia as in its judgment alone shall be necessary for the purpose of providing suitable and adequate quarters for the performance of its functions. After September 1, 2000, the Board may also use such assessments to acquire, in its own name, a site or building (in addition to the facilities existing on such date) to provide for the performance of the functions of the Board. After approving such plans, estimates, and specifications as it shall have caused to be prepared, the Board may, notwithstanding any other provision of law, cause to be constructed on any site so acquired by it a building or buildings suitable and adequate in its judgment for its purposes and proceed to take all such steps as it may deem necessary or appropriate in connection with the construction, equipment, and furnishing of such building or buildings. The Board may maintain, enlarge, or remodel any building or buildings so acquired or constructed and shall have sole control of such building or buildings and space therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/243?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§243. Assessments upon Federal reserve banks to pay expenses","tname":"Banks and Banking","by":{"3":"38"}},{"t":"usc","label":"19 U.S.C. § 58c","url":"https://www.law.cornell.edu/uscode/text/19/58c","by":{"3":"39"}},{"t":"usc","label":"19 U.S.C. § 2111","url":"https://www.law.cornell.edu/uscode/text/19/2111","by":{"3":"39"}},{"t":"usc","label":"26 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/26/1","stext":{"head":"§1. Tax imposed","paras":[[0,"(a) Married individuals filing joint returns and surviving spouses"],[0,"There is hereby imposed on the taxable income of—"],[1,"(1) every married individual (as defined in section 7703) who makes a single return jointly with his spouse under section 6013, and"],[1,"(2) every surviving spouse (as defined in section 2(a)),"],[0,"a tax determined in accordance with the following table:"],[0,"(b) Heads of households"],[0,"There is hereby imposed on the taxable income of every head of a household (as defined in section 2(b)) a tax determined in accordance with the following table:"],[0,"(c) Unmarried individuals (other than surviving spouses and heads of households)"],[0,"There is hereby imposed on the taxable income of every individual (other than a surviving spouse as defined in section 2(a) or the head of a household as defined in section 2(b)) who is not a married individual (as defined in section 7703) a tax determined in accordance with the following table:"],[0,"(d) Married individuals filing separate returns"],[0,"There is hereby imposed on the taxable income of every married individual (as defined in section 7703) who does not make a single return jointly with his spouse under section 6013, a tax determined in accordance with the following table:"],[0,"(e) Estates and trusts"],[0,"There is hereby imposed on the taxable income of—"],[1,"(1) every estate, and"],[1,"(2) every trust,"],[0,"taxable under this subsection a tax determined in accordance with the following table:"],[0,"(f) Phaseout of marriage penalty in 15-percent bracket; adjustments in tax tables so that inflation will not result in tax increases"],[0,"(1) In general"],[1,"Not later than December 15 of 1993, and each subsequent calendar year, the Secretary shall prescribe tables which shall apply in lieu of the tables contained in subsections (a), (b), (c), (d), and (e) with respect to taxable years beginning in the succeeding calendar year."],[0,"(2) Method of prescribing tables"],[1,"The table which under paragraph (1) is to apply in lieu of the table contained in subsection (a), (b), (c), (d), or (e), as the case may be, with respect to taxable years beginning in any calendar year shall be prescribed—"],[2,"(A) except as provided in paragraph (8), by increasing the minimum and maximum dollar amounts for each bracket for which a tax is imposed under such table by the cost-of-living adjustment for such calendar year, determined—"],[3,"(i) except as provided in clause (ii), by substituting \"1992\" for \"2016\" in paragraph (3)(A)(ii), and"],[3,"(ii) in the case of adjustments to the dollar amounts at which the 36 percent rate bracket begins or at which the 39.6 percent rate bracket begins, by substituting \"1993\" for \"2016\" in paragraph (3)(A)(ii),"],[2,"(B) by not changing the rate applicable to any rate bracket as adjusted under subparagraph (A), and"],[2,"(C) by adjusting the amounts setting forth the tax to the extent necessary to reflect the adjustments in the rate brackets."],[0,"(3) Cost-of-living adjustment"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The cost-of-living adjustment for any calendar year is the percentage (if any) by which—"],[3,"(i) the C-CPI-U for the preceding calendar year, exceeds"],[3,"(ii) the CPI for calendar year 2016, multiplied by the amount determined under subparagraph (B)."],[0,"(B) Amount determined"],[2,"The amount determined under this clause is the amount obtained by dividing—"],[3,"(i) the C-CPI-U for calendar year 2016, by"],[3,"(ii) the CPI for calendar year 2016."],[0,"(C) Special rule for adjustments with a base year after 2016"],[2,"For purposes of any provision of this title which provides for the substitution of a year after 2016 for \"2016\" in subparagraph (A)(ii), subparagraph (A) shall be applied by substituting \"the C-CPI-U for calendar year 2016\" for \"the CPI for calendar year 2016\" and all that follows in clause (ii) thereof."],[0,"(4) CPI for any calendar year"],[1,"For purposes of paragraph (3), the CPI for any calendar year is the average of the Consumer Price Index as of the close of the 12-month period ending on August 31 of such calendar year."],[0,"(5) Consumer Price Index"],[1,"For purposes of paragraph (4), the term \"Consumer Price Index\" means the last Consumer Price Index for all-urban consumers published by the Department of Labor. For purposes of the preceding sentence, the revision of the Consumer Price Index which is most consistent with the Consumer Price Index for calendar year 1986 shall be used."],[0,"(6) C-CPI-U"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"C-CPI-U\" means the Chained Consumer Price Index for All Urban Consumers (as published by the Bureau of Labor Statistics of the Department of Labor). The values of the Chained Consumer Price Index for All Urban Consumers taken into account for purposes of determining the cost-of-living adjustment for any calendar year under this subsection shall be the latest values so published as of the date on which such Bureau publishes the initial value of the Chained Consumer Price Index for All Urban Consumers for the month of August for the preceding calendar year."],[0,"(B) Determination for calendar year"],[2,"The C-CPI-U for any calendar year is the average of the C-CPI-U as of the close of the 12-month period ending on August 31 of such calendar year."],[0,"(7) Rounding"],[0,"(A) In general"],[2,"If any increase determined under paragraph (2)(A), section 63(c)(4), section 68(b)(2) or section 151(d)(4) is not a multiple of $50, such increase shall be rounded to the next lowest multiple of $50."],[0,"(B) Table for married individuals filing separately"],[2,"In the case of a married individual filing a separate return, subparagraph (A) (other than with respect to sections 63(c)(4) and 151(d)(4)(A)) shall be applied by substituting \"$25\" for \"$50\" each place it appears."],[0,"(8) Elimination of marriage penalty in 15-percent bracket"],[1,"With respect to taxable years beginning after December 31, 2003, in prescribing the tables under paragraph (1)—"],[2,"(A) the maximum taxable income in the 15-percent rate bracket in the table contained in subsection (a) (and the minimum taxable income in the next higher taxable income bracket in such table) shall be 200 percent of the maximum taxable income in the 15-percent rate bracket in the table contained in subsection (c) (after any other adjustment under this subsection), and"],[2,"(B) the comparable taxable income amounts in the table contained in subsection (d) shall be ½ of the amounts determined under subparagraph (A)."],[0,"(g) Certain unearned income of children taxed as if parent's income"],[0,"(1) In general"],[1,"In the case of any child to whom this subsection applies, the tax imposed by this section shall be equal to the greater of—"],[2,"(A) the tax imposed by this section without regard to this subsection, or"],[2,"(B) the sum of—"],[3,"(i) the tax which would be imposed by this section if the taxable income of such child for the taxable year were reduced by the net unearned income of such child, plus"],[3,"(ii) such child's share of the allocable parental tax."],[0,"(2) Child to whom subsection applies"],[1,"This subsection shall apply to any child for any taxable year if—"],[2,"(A) such child—"],[3,"(i) has not attained age 18 before the close of the taxable year, or"],[3,"(ii)(I) has attained age 18 before the close of the taxable year and meets the age requirements of section 152(c)(3) (determined without regard to subparagraph (B) thereof), and"],[3,"(II) whose earned income (as defined in section 911(d)(2)) for such taxable year does not exceed one-half of the amount of the individual's support (within the meaning of section 152(c)(1)(D) after the application of section 152(f)(5) (without regard to subparagraph (A) thereof)) for such taxable year,"],[2,"(B) either parent of such child is alive at the close of the taxable year, and"],[2,"(C) such child does not file a joint return for the taxable year."],[0,"(3) Allocable parental tax"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"allocable parental tax\" means the excess of—"],[3,"(i) the tax which would be imposed by this section on the parent's taxable income if such income included the net unearned income of all children of the parent to whom this subsection applies, over"],[3,"(ii) the tax imposed by this section on the parent without regard to this subsection."],[2,"For purposes of clause (i), net unearned income of all children of the parent shall not be taken into account in computing any exclusion, deduction, or credit of the parent."],[0,"(B) Child's share"],[2,"A child's share of any allocable parental tax of a parent shall be equal to an amount which bears the same ratio to the total allocable parental tax as the child's net unearned income bears to the aggregate net unearned income of all children of such parent to whom this subsection applies."],[0,"(C) Special rule where parent has different taxable year"],[2,"Except as provided in regulations, if the parent does not have the same taxable year as the child, the allocable parental tax shall be determined on the basis of the taxable year of the parent ending in the child's taxable year."],[0,"(4) Net unearned income"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"net unearned income\" means the excess of—"],[3,"(i) the portion of the adjusted gross income for the taxable year which is not attributable to earned income (as defined in section 911(d)(2)), over"],[3,"(ii) the sum of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§1. Tax imposed","tname":"Internal Revenue Code","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/26/11","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/26/1401","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 2001","url":"https://www.law.cornell.edu/uscode/text/26/2001","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/26/3101","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 3301","url":"https://www.law.cornell.edu/uscode/text/26/3301","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 4081","url":"https://www.law.cornell.edu/uscode/text/26/4081","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 4131","url":"https://www.law.cornell.edu/uscode/text/26/4131","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 4401","url":"https://www.law.cornell.edu/uscode/text/26/4401","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 5001","url":"https://www.law.cornell.edu/uscode/text/26/5001","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 5701","url":"https://www.law.cornell.edu/uscode/text/26/5701","by":{"3":"36"}},{"t":"usc","label":"26 U.S.C. § 5891","url":"https://www.law.cornell.edu/uscode/text/26/5891","by":{"3":"36"}},{"t":"reg","label":"47 C.F.R. § 54.308","url":"https://www.ecfr.gov/current/title-47/section-54.308","subs":["(a)","(g)","(h)"],"by":{"3":"78","4":"19, 20, 20"}},{"t":"reg","label":"47 C.F.R. § 54.309","url":"https://www.ecfr.gov/current/title-47/section-54.309","subs":["(a)"],"by":{"3":"78","4":"20, 19"}},{"t":"reg","label":"47 C.F.R. § 54.322","url":"https://www.ecfr.gov/current/title-47/section-54.322","subs":["(g)","(h)(3)","(j)"],"by":{"3":"78","4":"19, 20, 20","5":"21"}},{"t":"reg","label":"47 C.F.R. § 54.703","url":"https://www.ecfr.gov/current/title-47/section-54.703","by":{"3":"8"}},{"t":"reg","label":"47 C.F.R. § 54.712","url":"https://www.ecfr.gov/current/title-47/section-54.712","subs":["(a)"],"by":{"3":"10","5":"16"}},{"t":"reg","label":"Third Quarter 1998 Universal Service Contribution Factors Revised and Approved, 63 Fed. Reg. 35,930","url":"https://www.govinfo.gov/link/fr/63/35930","by":{"3":"11"}},{"t":"case","label":"PennEast Pipeline Co., LLC v. New Jersey","cite":"594 U.S. 482","y":2021,"id":"2020/19-1039","sc":1,"sum":"A certificate of public convenience and necessity issued by the Federal Energy Regulatory Commission pursuant to §717f(h) of the Natural Gas Act authorizes a private company to condemn all necessary rights-of-way, whether owned by private parties or States.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"15"}},{"t":"case","label":"Pensacola Tel. Co. v. W. Union Tel. Co.","cite":"96 U.S. 1","y":1877,"id":"scdb/1877-169","sc":1,"sum":"In 1859, an association of persons, known as the Pensacola Telegraph Company, erected a line of electric telegraph upon the right of way of the Alabama and Florida railroad, from Pensacola, in Florida, to Pollard, in Alabama, about six miles north of the Florida line. The company operated the whole line until 1862, when, upon the evacuation of Pensacola by the Confederate forces, the wire was taken down for …","sumSrc":"Headnote (U.S. Reports)","by":{"4":"11"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"op":1,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Watson v. Philip Morris Co.","cite":"551 U.S. 142","y":2007,"id":"2006/05-1284","sc":1,"sum":"The Court ruled that Philip Morris could not remove its case to federal court, because it was not \"acting under a federal officer\" in the sense of the statute. Justice Breyer wrote that \"broad language is not limitless.","sumSrc":"Oyez","by":{"4":"15"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"4":"10"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"4":"9, 11"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"4":"11"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"4":"15"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"4":"17"}},{"t":"reg","label":"47 C.F.R. § 1.41","url":"https://www.ecfr.gov/current/title-47/section-1.41","by":{"4":"17"}},{"t":"reg","label":"47 C.F.R. § 1.106","url":"https://www.ecfr.gov/current/title-47/section-1.106","by":{"4":"17"}},{"t":"reg","label":"47 C.F.R. § 1.115","url":"https://www.ecfr.gov/current/title-47/section-1.115","by":{"4":"17"}},{"t":"reg","label":"47 C.F.R. § 1.401","url":"https://www.ecfr.gov/current/title-47/section-1.401","by":{"4":"17"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"op":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"10"}},{"t":"case","label":"Gulf States Utils. Co. v. Fed. Power Comm’n","cite":"411 U.S. 747","y":1973,"id":"1972/71-1178","sc":1,"sum":"Following petitioner's application under § 204 of the Federal Power Act to respondent Federal Power Commission (FPC) for authorization of a bond issue, two intervening cities opposed the authorization on the ground that the proceeds of the bond issue would be used to finance or refinance certain anticompetitive activities in violation of the antitrust laws, the Federal Power Act, and the Public Utility Holding …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"14"}},{"t":"case","label":"Rural Cellular Ass’n v. FCC","cite":"685 F.3d 1083","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/685/1083/","by":{"5":"17"}},{"t":"case","label":"Wis. Bell v. United States ex rel. Heath","cite":"604 U.S. ___","y":2025,"court":"U.S. Feb. 21","sc":1,"by":{"5":"18"}},{"t":"reg","label":"47 C.F.R. § 63.71","url":"https://www.ecfr.gov/current/title-47/section-63.71","by":{"5":"18"}}]};